"""Rebuild the complete user guide. Requires ReportLab and Pillow outside FreeCAD."""
from pathlib import Path
import json,re,html,io,os,sys
from reportlab.pdfgen.canvas import Canvas
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,PageBreak,Table,TableStyle,Image,KeepTogether
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from PIL import Image as PILImage
ROOT=Path(__file__).resolve().parents[1];DOC=ROOT/'docs';OUT=Path(os.environ.get('ROTORFORGE_HELP_OUTPUT',str(ROOT/'build'/'RotorForge_Help.pdf')))
sys.path.insert(0,str(ROOT))
from freecad.rotorforge.version import __version__
from freecad.rotorforge.parameters import Parameters,ENUMERATIONS,RETIRED_PARAMETERS
from freecad.rotorforge.editor_sections import HIDDEN_FIELDS
for name,f in [('Body','DejaVuSans.ttf'),('Bold','DejaVuSans-Bold.ttf')]:pdfmetrics.registerFont(TTFont(name,'/usr/share/fonts/truetype/dejavu/'+f))
pdfmetrics.registerFontFamily('Body',normal='Body',bold='Bold')
INK=colors.HexColor('#262a2f');ACCENT=colors.HexColor('#08798a');PALE=colors.HexColor('#f1f2f3');LINE=colors.HexColor('#d4d6d8')
styles={k:ParagraphStyle(k,fontName='Bold' if k in ('title','h','sub') else 'Body',fontSize=size,leading=lead,textColor=INK,spaceAfter=space) for k,size,lead,space in [('title',27,33,20),('h',21,27,15),('sub',12,16,9),('body',9.6,14.2,9),('cell',9,12.7,0),('small',8,11.5,7),('caption',8.2,11.7,12)]}
styles['caption'].textColor=ACCENT
styles['h'].keepWithNext=True;styles['sub'].keepWithNext=True
styles['body'].allowOrphans=0;styles['body'].allowWidows=0
controls=json.loads((DOC/'help_controls.json').read_text());used=set();story=[];chapters=[]
# Refuse documentation with missing/retired controls or stale dropdown choices.
assert {c['key'] for c in controls}==set(Parameters.__dataclass_fields__)-set(HIDDEN_FIELDS)
for control in controls:
 assert control['key'] not in RETIRED_PARAMETERS
 assert control['default']==getattr(Parameters(),control['key'])
 if control['key'] in ENUMERATIONS:assert control['choices']==list(ENUMERATIONS[control['key']])
def p(text,style='body'):return Paragraph(text,styles[style])
def para(text):story.append(p(text))
def sub(text):story.append(p(text,'sub'))
CONTENT_WIDTH=A4[0]-116  # Account for the frame's 6 pt inset on both sides.
def table(rows,widths=(161,318),padding=5):
 head=ParagraphStyle('head',parent=styles['cell'],textColor=colors.white,fontName='Bold')
 data=[[Paragraph('Control',head),Paragraph('What it does',head)]]+[[p(str(a),'cell'),p(str(b),'cell')] for a,b in rows]
 t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('BACKGROUND',(0,0),(-1,0),INK),('TEXTCOLOR',(0,0),(-1,0),colors.white),('ROWBACKGROUNDS',(0,1),(-1,-1),[PALE,colors.white]),('BOX',(0,0),(-1,-1),.4,LINE),('INNERGRID',(0,1),(-1,-1),.3,LINE),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),padding),('BOTTOMPADDING',(0,0),(-1,-1),padding)]))
 t.spaceAfter=14;story.append(t)
def fields(keys=None,tab=None,prefix=None,padding=5):
 rows=[]
 for c in controls:
  if c['key'] in used:continue
  if keys is not None and c['key'] not in keys:continue
  if tab and c['tab']!=tab:continue
  if prefix and not c['key'].startswith(prefix):continue
  used.add(c['key']);desc=html.escape(c['help'])
  choices=c['choices']
  if choices and len(choices)<=8:desc+='<br/><b>Choices:</b> '+html.escape('; '.join(choices))+'.'
  default=str(c['default']).lower() if isinstance(c['default'],bool) else str(c['default'])

  rows.append((html.escape(c['label']),desc))
 if rows:table(rows,padding=padding)
def figure(name,caption,width=479,height=230):
 path=DOC/name
 with PILImage.open(path) as im:w,h=im.size
 scale=min(width/w,height/h)
 # One unsplittable cell owns image, caption and padding; no floating elements.
 block=Table([[[Image(str(path),w*scale,h*scale),Spacer(1,9),p(caption,'caption')]]],colWidths=[CONTENT_WIDTH])
 block.setStyle(TableStyle([('LEFTPADDING',(0,0),(-1,-1),0),('RIGHTPADDING',(0,0),(-1,-1),0),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),14)]))
 story.append(block)
from reportlab.platypus.doctemplate import ActionFlowable
class ChapterBreak(ActionFlowable):
 def apply(self,doc):
  if not doc.frame._atTop:doc.handle_pageBreak()
def chapter(title):
 story.append(ChapterBreak());index=len(chapters)+1;key='chapter-'+str(index);chapters.append((title,key));story.append(p(f'<a name="{key}"/> {index:02d}  {html.escape(title)}','h'))
# Cover and technical figures share the current engineering illustration style.
story.extend([Spacer(1,32),p('RotorForge','title'),p('Drone Frame Editor<br/>Complete user guide','h'),p(f'Version {__version__} • Michael Struggl','body')])
figure('CoverFrame.png','RotorForge frame designed by Michael Struggl.',height=250)
para('Design the motor layout, carbon plates, arm joints, electronics mounts and cutting profiles in one editable FreeCAD project. This guide follows the editor workflow and describes every visible parameter and command in its relevant chapter.')
para('Dimensions are in millimetres unless stated otherwise. Frame +Y is forward, +X is right and +Z is up. Open the separate Installation PDF for Windows, macOS and Linux installation paths.')
story.append(PageBreak());story.append(p('Contents','h'));toc_marker=len(story);story.append(Spacer(1,5))
para('Use the linked chapter names to navigate. Tables use the names shown in the editor. Defaults describe a fresh frame; loading saved settings keeps that design\'s values. Disabled controls retain their settings for when the relevant mode is enabled.')
chapter('Start a frame and use the editor')
para('Install the complete RotorForge folder in your FreeCAD user Mod directory. Confirm the file freecad/rotorforge/init_gui.py inside that folder. Close FreeCAD and replace the old folder completely when upgrading; merging folders can leave obsolete startup files behind. The Installation PDF gives the steps for each operating system.')
para('Activate the RotorForge workbench, choose New frame, set the plate design and motor layout, then work through the tabs. The top view updates as dimensions change. The FreeCAD model is created only when you press Create frame; editing an existing model uses Update frame.')
para('Start with the main proportions, then fit the arm roots, stack, standoffs and FPV hardware. Set plate reaches and centre widths before placing airflow openings or edge notches. The Checks area reports geometric errors and layout warnings. Correct blocking errors before building or exporting.')
table([('New frame','Opens an editor for another parametric frame.'),('Edit frame','Edits the selected frame, parameter object or part. With one frame in the document it can be found automatically.'),('Create frame / Update frame','Creates the assembly or rebuilds affected components and their dependent parts. Detailed part and clearance checks can still reject a configuration that passed the fast editor checks.'),('Cancel','Closes the editor without committing its frame changes.'),('Maximize window / Restore window','Toggles the editor between a maximized window and its previous size. The normal window controls remain available.'),('Front isometric','Looks toward the +Y nose of the assembled frame.'),('Toggle references','Shows or hides approximate propeller, motor, stack and FPV electronics envelopes. These are references, not manufacturing parts.'),('Help manual (PDF)','Opens this guide in the system PDF viewer.'),('Load settings / Save settings','Loads or saves a frame JSON. Save the FreeCAD project separately to retain the generated model and cutting layouts.'),('Export frame','Writes manufacturing files and refreshes the native cutting-profile layout. The export chapter explains the thickness sheets and coordinate systems.')])
story.append(PageBreak())
sub('Where to find controls')
para('The main categories contain focused pages underneath. Choose a main tab first, then the page for the part you want to edit. Group headings separate related dimensions within each page. Disabled fields keep their saved values until the relevant design mode is enabled.')
table([('Frame','Layout: plate design, FPV, wheelbase and propellers.<br/>Bottom / Mid / Top plate: outline, reaches, end shapes, fillets and thickness; top-front camera recess.<br/>Centre widths: widening and shoulders.'),('Arms','Roots: beams, fitted joints and root dimensions.<br/>Bolts: spacing, coordinates and stack reliefs.<br/>Clamps &amp; key: arm sandwich and keystone.<br/>Motors: pad outline, rotation and fixing pattern.'),('Hardware','Standoffs: counts, positions and heights.<br/>Stack: FC/ESC pattern, offsets and screw access.<br/>Straps: one/two straps, slots or outline cutouts.<br/>Nut retention: hex pockets and press nuts.<br/>Weight estimates: equipment masses.'),('Battery','Placement: LiPo size, mass, mounting face and pose.<br/>LiPo pad: outline, reaches, grip and density.'),('FPV','Camera: body dimensions and side screws.<br/>Tilt &amp; position: fixed/variable tilt and fitting.<br/>Side plates: contacts, captured tabs and reliefs.<br/>VTX: mounting holes and envelope.'),('TPU','Appearance: shared printed-part colour.<br/>Camera isolation, Front bumper and Motor protectors.<br/>Side guards: fit mode, VTX clearance, USB and wire access.<br/>Side guard vents: separate VTX/FC sections.<br/>Side guard straps: top/bottom strap passages.'),('Finishing','Detailed references: motors, props, stack, camera, VTX and LiPo.<br/>Airflow / outlines: cuts, notches and patterns.<br/>Checks: minimum material, density and visibility.')],padding=3)
sub('Find a control')
para('Use the search field above the tabs when you know a control name or topic. Type a term such as keystone, strap or camera tilt, then select a result. The editor opens both tab levels and scrolls to the field. Results include fit buttons and airflow pattern controls. Searching does not change parameter values or enable a disabled option. Clear the search field with its small clear button to start another search.')
story.append(PageBreak())
sub('Inspect one part or all flat profiles')
para('Use the preview selector above the drawing to switch between Overall frame, All parts, All four arms, or one active component. Individual parts automatically fit the available space; arms are aligned motor-end upward for inspection. Plate and arm views include their fixing holes, access slots, tip features, applied airflow openings and edge notches. Camera sides appear as flat profiles rather than their thin assembled top edges. Inactive parts disappear from the selector when you change the plate or locking options. This inspection creates no FreeCAD document objects and does not change the exported CNC layout.')
para('The overall view shows the LiPo footprint in orange when references are visible. After Calculate frame weight / CG, a red cross marks the active estimate CG projected into the top view (equipped plus LiPo when both estimates are enabled). A design or mass-setting change clears the old mass/CG result and marker until you calculate again. Changing only colour or the preview selection keeps the result.')
para('Carbon arms, plates, clamps, keys and camera side plates use satin graphite in the model. TPU > Appearance selects one matte colour for every printed or soft part, including the LiPo pad. Electronics reference colours are independent. The guide uses matching orthographic diagrams: grey carbon, darker-grey soft/printed parts, neutral hardware and amber reference electronics. Lighter grey separates overlapping carbon layers. Shape catalogues follow the same grey palette; teal is reserved for captions and navigation. Colours in the guide identify parts; choose the desired model colour in the editor.')
figure('BatteryEditor.png','Overall and separate-part views help inspect the frame, top plate, arms and LiPo pad before creation.',height=300)
chapter('Motor layout and frame proportions')
para('Diagonal wheelbase sets the base distance between opposite motor centres. It is not the length of a plate or the overall carbon outline. True X is symmetric. Stretched X increases the left/right motor span on the roll axis. Deadcat widens the front motor pair and automatically compensates rear reach as front spread increases. With zero extra rear extension, both diagonals retain the configured wheelbase.')
figure('Frame.png','The frame uses +Y at the front. Arm names refer to physical positions, not flight-controller motor numbering.',height=230)
fields(tab='Layout')
sub('Independent Deadcat rear arm length')
para('On Frame &gt; Layout, increase Deadcat rear arm extension to lengthen both rear arms by the entered amount. For example, 20 mm adds 20 mm to each rear root-to-motor length. The motors move outward along the existing arm axes, without moving the front motors or the arm-root references. The rear fixing pattern and motor pad follow the motor. Zero restores the original layout. True X and Stretched X ignore this value but keep it saved.')
para('An extension increases the final rear span and motor diagonal. While it is active, the wheelbase and front/rear span controls are labelled as base values; the summary shows the actual diagonal and front/rear arm lengths. Propeller clearance, preview, generated arms and manufacturing exports follow the extended positions.')
para('Propeller diameter and desired prop gap compare the propeller discs. They do not change the motor locations automatically. Review the resulting minimum gap and the camera view against the actual propellers and camera lens.')
chapter('Plate arrangements, reaches and centre widths')
para('A two-plate frame has a bottom and top. Arms may sit above or below the bottom, with one optional clamp on the opposite side of the arms. The FC stack sits on the upper clamp when arms are above the bottom; below-bottom arms keep the stack on the bottom plate. A three-plate frame sandwiches the arms between bottom and mid. The bottom nose extends toward the camera; the mid body runs from the stack toward the rear.')
figure('PlateLevels.png','Plate thicknesses and arm position determine the mounting levels used by the stack, standoffs and camera cage.',height=210)
sub('Choose the base outline of each plate')
para('Bottom, mid and top plates each have their own outline selector. The clamp selector applies to whichever upper or lower clamp is active. Rounded rectangle retains the original shape. Chamfered rectangle clips the corners using the common corner radius; Octagonal uses broader facets. Tapered front and Tapered rear narrow the named end. Hexagonal narrows both ends; Faceted shield keeps broad rear shoulders and tapers the nose. Plate end width controls the narrow ends as a percentage of base width. The stack, bolts and standoffs do not move with the outline.')
fields(keys=['BottomPlateShape','MidPlateShape','TopPlateShape','ClampPlateShape','PlateEndWidth'])
figure('PlateOutlineOptions.png','Seven base outlines. Centre widening, arm-matched tabs and applied cutouts are added to the selected base.',height=245)
sub('Shape the absolute front of the bottom plate')
para('Open Frame / Bottom plate / Front edge. This is separate from the base outline selector and affects only the bottom plate nose. Straight keeps the existing edge. Rounded nose makes a smooth convex cap; Pointed nose meets at a central tip; Flat-tip nose leaves a small central flat; Swept shoulders blend smoothly into a flat tip. Concave nose makes a smooth central recess, V-notch makes an angular recess, and Twin lobes makes two rounded tips with a shallow central dip.')
figure('BottomNoseShapes.png','Profile views of the original eight bottom-front options. Front is upward; each example uses 6 mm shaping depth.',height=360)
figure('BottomNoseMoreShapes.png','Six additional bottom-front profiles, using the same 6 mm shaping zone.',height=285)
story.append(PageBreak())
fields(keys=['BottomNoseShape','BottomNoseDepth','BottomNoseTipWidth'])
para('Front edge depth controls the length of the shaping zone. Stepped nose has two shoulder levels; Shallow W and Triple scallop create repeated recesses; Arrowhead leaves a narrow central point; Flat recess and Round U recess leave a central opening. Front tip width controls Flat-tip nose, Swept shoulders, Stepped nose, Flat recess and Round U recess; it is a percentage of the nose span. The span follows the local width at the nose; widening only the middle leaves the nose shape unchanged. The front reach remains the forward limit: these shapes trim material inside it and never extend the plate. Centre widening cannot fill the nose back in. Existing base corners, outline cutouts and the bottom plate fillet still apply. Arm and standoff fixings retain their coordinates and material checks. When Follow plates is enabled, camera contacts and their sockets can move rearward to retain full support on the new nose. Manual camera attachment positions keep their support checks. If a deeper shape removes required support, reduce its depth or increase the bottom front reach. Other plate base outlines and motor arms keep their own settings; camera-following sockets follow the fitted camera cage. Shaped fronts are included in cutting profiles; smooth fronts use exact cubic splines in DXF and cubic paths in SVG.')
story.append(PageBreak())
sub('Top-front shapes for camera uptilt')
para('Open Frame &gt; Top plate &gt; Front edge and camera recess. Straight keeps the current front. The selector also offers the general front profiles shown in the bottom-front catalogue, plus six camera-specific recesses. These shapes open the centre while keeping side rails for the upper camera tabs. They trim inside the existing top front reach and work in either plate design, including non-FPV frames.')
para('The U recess has a flat back with rounded inner corners. Flared recess opens toward the front with a narrower back. Swept recess uses curved shoulders; Crescent makes a smooth bowl. Stepped recess narrows in two stages, and Chamfered recess uses straight sides with clipped rear corners. Every recess is symmetric about the frame centreline.')
fields(keys=['TopFrontShape','TopFrontDepth','TopFrontTipWidth','TopFrontRecessWidth','TopFrontClearance','TopFrontSetback'])
para('For camera-specific shapes, the shoulder line is <b>Top front reach - Camera shoulder setback</b>. The deepest point is another Front edge depth behind that line. For example, a 90 mm front reach, 6 mm setback and 16 mm depth put the shoulders at Y = 84 mm and the deepest part of the recess at Y = 68 mm. Setback is useful when the plate corners project too far forward. Recess width is in millimetres; zero follows the camera body width plus twice Camera recess clearance. Flared and swept mouths can be 20% wider, while stepped and flared backs are narrower. General front profiles use the percentage Front feature width where applicable and ignore the camera-specific width and setback.')
story.append(PageBreak())
sub('Camera recess catalogue')
figure('TopFrontCameraShapes.png','Top-front profiles create the complete camera recess. Front is upward (+Y). Tab sockets follow the supported camera contacts.',height=390)
figure('TopFrontSetback.png','Teal marks the original front reach. A recess opens the centre; shoulder setback also retracts the outside front edge.',height=160)
para('The top-front profile defines the camera opening. Its width, depth, clearance and shoulder setback are all on Frame &gt; Top plate. Straight keeps a solid front. Tilt and camera position remain independent. Follow plates refits the upper contact and sockets; custom attachments retain support checks. The builder checks the configured camera envelope through the tilt range. Adjust depth, width, reach or standoff height if clearance or mounting stock is insufficient.')
story.append(PageBreak())
sub('Rear edge shapes on each deck')
para('Frame &gt; Bottom plate, Mid plate and Top plate each have independent Rear edge controls. Bottom rear shaping is active only with two plates; the mid rear selector is active only with three. Top rear shaping works in both designs. Straight preserves the existing end. The rear library mirrors all 14 front profiles toward -Y and adds Cable channel, Dual cable channels, Split tail and Stepped electronics tail. These profiles trim inside the current rear reach; they do not move holes or extend the plate.')
para('Rear edge depth sets the shaping zone along the frame. Rear feature width changes the flat, step or recess span in profiles that use it. A cable channel has rounded inner corners; Dual cable channels leaves a central bridge. Split tail creates a rectangular central opening, and Stepped electronics tail leaves a narrower central tongue. These names describe outlines; they do not create antenna or GPS holders. Check connector and wire access yourself.')
rear_rows=[]
for prefix,label,mode in (('BottomRear','Bottom','two-plate designs'),('MidRear','Mid','three-plate designs'),('TopRear','Top','both plate designs')):
 for suffix,control,description in (('Shape','rear shape','Independent rear outline for '+mode+'. Straight retains the current end.'),('Depth','rear depth','Shaping depth in mm, limited to half this plate length.'),('TipWidth','rear feature width','Percentage of the rear span used by flat tips, steps and recesses.')):
  used.add(prefix+suffix);rear_rows.append((label+' '+control,description))
table(rear_rows)
para('Required stock around standoffs, VTX holes, camera sockets and arm bolts is still checked. If an edge profile removes support, use a shallower depth, a wider tip or a longer rear reach. Base outlines, centre widening, outline cutouts and optional corner fillets combine with the end profile. Side guards and a plate-following LiPo pad follow the resulting deck. Exported CNC profiles use the final shaped boundary.')
story.append(PageBreak())
sub('Rear edge catalogue')
figure('RearEdgeShapes.png','Rear is downward (-Y). Select the shape independently on each active rear deck.',height=610)
story.append(PageBreak())
sub('Independent front and rear body reaches')
para('Automatic reach starts from the configured base size and the support the design requires. Custom reach uses the entered limits and reports missing support instead of silently extending the plate. The plate-bounds readout shows the resulting rear/front Y coordinates.')
para('The mid front body is measured from the stack: <b>front Y = Stack Offset Y + Mid body reach ahead of stack</b>. The bottom rear body is measured the other way: <b>rear Y = Stack Offset Y - Bottom body reach behind stack</b>. Increase the bottom rear body reach to fill more of the centre opening between the rear arm tabs.')
para('The mid front clamping tabs follow the front arm roots; the bottom rear tabs follow the rear arm roots, including their width, taper, bolt positions, fitted joints and key pockets. These small arm-matched tabs can extend beyond the chosen main-body edge. The main body remains controlled by its own width and reach.')
fields(keys=['BottomReachMode','BodyLength','BottomFrontExtension','BottomFrontReach','BottomRearReach','BottomBodyRearReach','BodyWidth','BottomThickness','MidReachMode','MidFrontReach','MidRearReach','ClampThickness','TopReachMode','TopLength','TopFrontReach','TopRearReach','TopWidth','TopThickness','CornerRadius'])
figure('BottomStackReach.png','Bottom rear body reach is referenced to the FC stack. The rear tabs continue to match the arms beyond that body.',height=240)
figure('ArmMatchedMid.png','Front mid-plate tabs follow the actual arm-root footprint rather than creating broad independent overhangs.',height=220)
sub('Smooth plate and cutout corners')
para('Bottom, mid and top plates have independent corner fillet controls on their own Frame pages. The clamp fillet on Arms &gt; Clamps &amp; key applies to the active upper or lower clamp. Zero retains the finished plate. A positive target radius rounds outside corners, inward shoulders and outline notches after all cuts. Closed internal openings stay unchanged by default. Enable the separate Round internal openings checkbox for that plate to include their corners; each plate has its own switch, and the clamp switch follows the active clamp. Circular drills and already tangent slots retain their geometry, as do plate thickness and countersinks. It is separate from the base Corner radius and motor-pad transition blending.')
figure('PlateFillets.png','Profile previews with a 3 mm target: outside corners only (default), and internal cutout corners included by explicit choice. Mounting drills and tangent slots retain their geometry.',height=200)
fields(keys=['BottomEdgeFillet','BottomFilletOpenings','MidEdgeFillet','MidFilletOpenings','TopEdgeFillet','TopFilletOpenings','ClampEdgeFillet','ClampFilletOpenings'],padding=5)
para('The entered value is a target maximum, not a requirement that every corner have the same radius. A 3 mm target uses 3 mm where it fits and smaller local radii beside short edges, mounting footprints or narrow webs. This avoids rejecting the complete plate when one corner lacks space. The FreeCAD report lists local radius adjustments and any constrained corners retained to preserve the part. Inspect these messages and the generated shape when exact radii matter. The editor follows the same outside-only or internal-opening selection schematically; created parts and CNC profiles use the exact final arcs. Fillets do not repair a source cutout that already disconnects the plate or crosses protected hardware.')
story.append(PageBreak())
sub('A wider stack and arm-mounting section')
para('Each plate can widen around the stack independently of its normal base width. A value of zero disables the extra width. Full-width centre length defines the middle plateau; the shoulder length tapers it back to the ordinary width at both ends. The common centre Y shifts this section along the frame.')
fields(keys=['BottomCentreWidth','MidCentreWidth','TopCentreWidth','ClampCentreWidth','CentreSectionLength','CentreShoulderLength','CentreSectionY','ArmRootsFollowCentre'],padding=3)
chapter('Arms, fitted roots, bolts and locking')
para('Arm width sets the ordinary beam. A larger root width adds material only around the inner mounting region and tapers toward the beam. Root reference positions, tail extension and bolt coordinates are separate controls: moving a bolt does not move a motor or root reference.')
sub('Straight-axis beam designs')
para('The arm axes, roots, bolts and motors stay fixed. Choose a beam section on Arms &gt; Roots. Root taper adds material near the inner end; Motor flare adds a shoulder near the motor. Hourglass neck has wider ends and a straight narrower middle. Broad shoulder carries a long wide section, and Stepped beam has distinct straight shoulders. ')
para('Arm profile widening adds material around the straight centreline while keeping Arm width as the minimum beam width. Zero removes the extra widening. All six beam choices use solid carbon sections.')
figure('ArmBeamOptions.png','Six solid beam profiles around fixed straight axes. The roots, motor positions and bolt coordinates remain unchanged.',height=235)
fields(keys=['ArmBeamShape','ArmProfileAmount'])
sub('Arm corner fillets')
para('Arms use the same adaptive plan-view fillet system as the plates. Set the target radius on Arms &gt; Roots. Only corners beyond the root mounting area, on the beam and motor-pad outline, are rounded after custom cuts. The complete root outline, fitted joint and mounting stock remain unchanged. The protected length reaches at least Arm root length and extends farther if a custom arm bolt needs more supporting material. Radii reduce locally to preserve minimum webs. Thickness edges remain square. Closed internal openings are left unchanged unless Fillet arm internal openings is enabled. Circular fixing holes remain circular. Zero retains the existing outline; motor-pad transition blending is a separate control.')
figure('ArmFillets.png','Exact arm outlines before and after adaptive fillets, with bolt positions unchanged.',height=225)
fields(keys=['ArmEdgeFillet','ArmFilletOpenings'])
sub('Root fit and custom bolts')
para('Independent roots keep their rounded tails. Fitted miters trim each root at the shared joint lines so neighbouring arms can meet without overlapping. Zero joint clearance gives nominal contact where the tails reach; positive clearance creates a deliberate gap. Increase the tail reach or move roots inward if there is still space between them.')
para('Custom bolt coordinates use the <b>frame axes</b>, not the arm angle. The front-right root is the reference. X is mirrored for left arms and Y for rear arms. Bolt 1 is the inner shared-mount choice and bolt 2 the outer choice. Use current spacing for custom bolts copies the current along-arm pattern into these frame-aligned offsets.')
fields(keys=['ArmThickness','ArmWidth','ArmRootWidth','ArmRootLength','ArmRootTaperLength','ArmRootY','RootInset','RootExtension','ArmRootFit','ArmJointClearance','RootBoltLayout','RootBoltSpacing','RootBolt1X','RootBolt1Y','RootBolt2X','RootBolt2Y','RootHoleDiameter','ArmRootReliefsEnabled','ArmRootReliefShape'])
sub('Round reliefs or stack-screw escape slots')
para('On Arms &gt; Bolts, enable Relieve arm roots for stack access, then choose Arm stack relief shape. Round hole keeps the original circular cutout. Slot toward stack centre extends each intersecting relief through the inward arm edge, pointing at the actual FC stack centre rather than the frame origin. A nonzero Stack Offset Y moves that target as well.')
para('The slot width uses Stack screw access diameter on Hardware &gt; Stack, normally 6 mm. Only screws which cross that arm receive a slot. Slots remain present in the arm DXF/SVG and CNC profiles. Disabling reliefs preserves the selected shape for later.')
para('To replace an arm, release its arm bolts and any clamp or keystone capture, then slide the arm away from the stack screw along its open slot. Check the removal path against your actual screw heads and neighbouring parts. With multiple intersecting screws, confirm that their slot paths allow the intended movement. CAD creation still rejects slots that cut into arm-bolt bearing material or split an arm into separate pieces.')
figure('FittedArmRoots.png','Fitted root joints and the compact key pocket trim the arm tails while retaining the configured bolt and motor centres.',height=245)
sub('Two-plate clamps and keystone capture')
para('Enable Arm clamp plate (2 plates) to add one continuous clamp across all four roots. Arms above the bottom use one upper clamp, which also carries the FC stack. Arms below the bottom use one clamp beneath the arms, and the FC stack mounts directly on the bottom plate. This choice is independent of the keystone. The eight root bolts secure the bottom/arms/clamp sandwich.')
para('Both clamp ends follow the actual arm roots, using the same trimmed bolt-pad approach as the mid and bottom tabs in three-plate frames. Upper clamps retain stack mounting support and local standoff pads. Lower clamps retain service openings for the screws in the bottom plate. Arm width, taper, fitted joints and bolt locations update the tabs automatically. Upper and Lower clamp thickness retain independent values; only the active value is editable. Update existing frames and re-export after upgrading to remove an old extra upper clamp.')
figure('ClampArmFollow087.png','Arm-matched clamp ends: independent roots on the left and wider fitted roots on the right. Grey outlines show the arms; carbon fills show the finished clamp.',height=210)
para('In three-plate mode the bottom and mid capture the key. In fitted-miter mode, key width, length and outline define a compact pocket: diamond, chamfered diamond, hexagon or octagon. Each outline cuts a matching seat in the arms. Independent roots retain the automatic arm-following key. The key has stack-access reliefs; enabled arm-root reliefs also open material that crosses the stack service holes.')
figure('SingleClamp0871.png','Two-plate root sections: one lower clamp for arms below the bottom, or one upper clamp for arms above it. The optional key occupies the arm layer and needs no additional plate.',height=210)
figure('KeystoneShapes.png','Four compact fitted-miter key outlines. Matching arm seats use the same shape and the selected clearance.',height=150)
fields(keys=['TwoPlateArmPosition','ArmBracesEnabled','ArmBraceThickness','UndersideClampThickness','KeystoneEnabled','KeystoneShape','KeystoneWidth','KeystoneLength','KeystoneClearance'])
chapter('Motor mounting patterns and pad shapes')
para('Motor fixing holes use either a four-hole or three-hole bolt-circle pattern. Enter the measured diameter through the fixing-hole centres. The complete pattern and pad rotate outward with each arm, including Stretched X and Deadcat. Set the actual motor thread spacing and centre opening first, then choose an outline large enough to support them.')
fields(tab='Motors',prefix='Motor',padding=6)
sub('Shield outlines and optional neck reliefs')
para('The catalogue includes round, faceted and shield families. Shield variations use shallow circular edge scallops. Choose between swept or curved shoulders, a broad or compact deck, paired side recesses and single or split nose crowns. Corner / chamfer / scallop size controls their scallop depth. They are original parametric families rather than replacement arms for named commercial frames.')
para('Motor pad neck length extends the root-facing connection rather than the outward tip. Optional Neck slot, Twin neck holes and Twin neck slots remove material there, away from motor screws and the shaft bore. Width / diameter and full slot length remain editable. The neck needs enough length for the opening and required edge material. These optional cuts do not move mounting holes. The two retained extended-tip shapes keep their original tip-slot controls.')
figure('MotorPadReliefs.png','Optional reliefs in the root-facing neck of Round-shoulder shield. The motor bearing and fixing holes are kept clear.',height=155)
sub('Rotate complete pads with frame symmetry')
para('Motor pad rotation (mirrored), under Arms &gt; Motors, rotates each pad outline, fixing pattern and optional tip slot around its motor centre. Arm root bolts and main beam directions stay fixed. The selected pivot determines whether motor and prop centres move. Zero keeps pads aligned with their own arms. Positive values turn the front-right and rear-left pads counterclockwise in top view, and the front-left and rear-right clockwise. Negative values reverse those directions. The same rule applies to True X, Stretched X and Deadcat, using mirrored rotation signs. Motor centre mode retains the existing motor spans; Pad beginning mode changes the actual motor spans and diagonals.')
para('Motor hole rotation remains a separate adjustment within each pad and uses its own offset. Leave that offset at zero for a fully mirrored three-hole pattern. A manually clocked three-hole offset can intentionally differ from its reflected orientation. With round pads, look at the fixing pattern or tip features to see rotation. The live preview, exact CAD, slots and cutting profiles follow both controls. Check material around holes and the connection to the arm when using large angles.')
figure('MotorPadRotation.png','Plan views: opposite corners share a rotation sign. Motor centres (red) and arm/root positions stay fixed.',height=220)
sub('Choose where the motor pad rotates')
table([('Motor centre','The default pivot. The outline and its fixing holes turn about the motor shaft centre; motor and prop centres remain fixed.'),('Pad beginning','The pivot sits at the root-facing extent of the unrotated pad outline, measured along the original arm axis. Shapes with a longer neck therefore pivot farther inward. The motor centre swings around this fixed point, carrying its holes, centre bore, nose slots and motor/prop references.')])
sub('Rounded connections on rotated pads')
para('Rotated pad transition radius adds a planar rolling-radius blend at inward corners between the beam and a rotated pad. It adds local supporting material, retains square thickness edges, and works at either pivot with mirrored rotation. Zero keeps the original junction. Reduce the radius if the builder cannot construct the blend.')
para('Choose Motor pad rotation pivot under Arms &gt; Motors &gt; Pad outline, then adjust Motor pad rotation (mirrored). The beam retains its root and original axis, ends at the pad beginning and joins the moved pad through a continuous full arm-width elbow. Both the preview and the carbon CAD use this connection, including widened roots and their taper. At zero rotation, both pivot modes produce the same arm. Geometry checks reject disconnected arms and roots which leave too little room for the pad transition.')
para('In Pad beginning mode, the actual wheelbase diagonals, prop clearance and motor spans can change even though the entered base wheelbase stays the same. Review the moved prop discs and minimum gap after turning the pads. Cutting profiles and exports include the same connected shape, transformed fixing holes, pivot coordinates and motor positions. Existing projects keep Motor centre until you select the new mode.')
sub('Rotate a bolt-circle pattern')
para('Under Arms &gt; Motors, select a bolt-circle pattern and adjust Motor hole rotation. The angle follows each arm/pad direction in every layout. Use 45 degrees to turn a four-hole cross into square corners, or any signed angle to clock a three-hole pattern. Circle diameter stays constant: a 16 x 16 mm square needs about 22.627 mm bolt-circle diameter. Check hole support in the preview before building or exporting.')
sub('Motor and prop sizing actions')
para('Arms &gt; Motors includes Apply motor / prop sizing. Choose a 9, 12, 16 or 19 mm bolt-circle diameter to fill four-hole mounting geometry, pad width, fixing/centre bores, reference motor dimensions and a corresponding nominal prop size. A separate 9 mm bolt-circle / 1103 / 2-inch choice supports small motors. These sizing actions do not change the motor centres or silently resize the whole frame. Adjust wheelbase if the new props overlap. All dimensions remain editable.')
table([('9 mm bolt circle','Nominal 1404 motor body, 20 mm pad, M2 clearance holes and 3-inch props.'),('12 mm bolt circle','Nominal 1804 motor body, 25 mm pad, M2 clearance holes and 4-inch props.'),('16 mm bolt circle','Nominal 2207 motor body, 30 mm pad, M3 clearance holes and 5-inch props.'),('19 mm bolt circle','Nominal 2806.5 motor body, 36 mm pad, M3 clearance holes and 7-inch props.'),('9 mm bolt circle','Nominal 1103 motor body, 25 mm pad, M2 clearance holes and 2-inch props. Four holes at 90-degree intervals.')])
para('Simple references are approximate clearance cylinders; optional detailed shapes are on Finishing / Detailed references. Neither style is a branded CAD model or a motor/prop performance recommendation. Motor stator size does not uniquely define bolt pattern, bell size, KV, battery voltage or prop compatibility. Measure your actual parts and edit the reference dimensions. The simple prop reference is a full swept disc; the detailed option shows three blades. Guard clearance checks retain the swept propeller envelope. Only 4-hole bolt circle and 3-hole bolt circle modes are available. Circle diameter and square pitch are different measurements.')
fields(tab='Motor references')
para('Mounting examples reviewed: <link href="https://iflight-rc.eu/en-nl/products/xing2-1404-toothpick-ultralight-motor-unibell" color="#237588">iFlight XING2 1404</link> (9 x 9 mm), <link href="https://shop.iflight.com/iflight-manu8/xing2-1806-fpv-motor-1-5mm-shaft-pro1466" color="#237588">iFlight XING2 1806</link> (12 x 12 mm), <link href="https://shop.iflight.com/xing2-2207-4s-6s-fpv-motor-unibell-pro1464" color="#237588">iFlight XING2 2207</link> (16 x 16 mm), and <link href="https://www.t-hobby.com/products/brushless-motor-x8-fpv-drones-f90-2806-5" color="#237588">T-Motor F90</link> (larger motor family). The sizing actions use nominal bodies rather than claiming exact fit to these products.')
sub('Reading the motor-pad catalogue')
para('Catalogue views use zero pad rotation and share scale and colour: the arm continues left and the tip points right. They use 30 mm pads, 14 mm arms, 22.627 mm four-hole bolt circles at 45 degrees with 3.2 mm holes, a 9 mm centre bore and no tip slots. Pad width is nominal; shoulders and noses can extend beyond it. Each card lists its applicable controls. Corner/chamfer/scallop size affects only listed shapes. The original tip slot applies to Tapered nose and Arrowhead. The twelve shield variations use Motor pad neck length and the separate Additional pad cutouts selector. Outlines keep the entered motor centre and fixing pattern.')
sub('Practical profile references')
para('Commercial arm references reviewed for motor-bearing material, short tips and tapered necks: <link href="https://geprc.com/product/geprc-gep-mk5-frame-parts/" color="#237588">GEPRC MARK5 frame parts</link> and <link href="https://www.flyfish-rc.com/collections/spare-parts" color="#237588">FlyFishRC Volador spare arms</link>. The shield variations add shallow edge scallops, swept or curved shoulders, and short crowns around a solid mounting deck. They are original outlines rather than dimensioned copies of commercial parts. Measure actual motors and validate the finished design.')
catalogue=json.loads((DOC/'motor_pad_guide.json').read_text())
assert [item['name'] for item in catalogue]==next(c['choices'] for c in controls if c['key']=='MotorPadShape')
for start in range(0,len(catalogue),6):
 story.append(PageBreak())
 sub(f'Motor-pad catalogue {start//6+1} of {(len(catalogue)+5)//6}')
 para('Arm section to the left; outward motor nose to the right. All views use the same scale and colour.')
 cells=[]
 for item in catalogue[start:start+6]:
  path=DOC/'motor_catalogue'/(item['name'].replace(' ','_')+'.png')
  cells.append([p(html.escape(item['name']),'sub'),Image(str(path),208,108.333),Spacer(1,4),p(html.escape(item['description']),'cell'),Spacer(1,5),p('<b>Controls:</b> '+html.escape(item['controls']),'small')])
 if len(cells)%2:cells.append([])
 grid=Table([cells[i:i+2] for i in range(0,len(cells),2)],colWidths=[CONTENT_WIDTH/2]*2,hAlign='LEFT')
 grid.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),12),('LINEBELOW',(0,0),(-1,-1),.35,LINE)]))
 story.append(grid)
chapter('FC stack mounting and screw access')
para('Choose one of the two FC stack patterns: 20 x 20 mm or 30.5 x 30.5 mm. Both are centre-to-centre square pitches. Stack spacer height and stack clearance height remain editable.')
para('The stack sits on the bottom in a two-plate design without a clamp or with below-bottom arms. With above-bottom arms and the clamp enabled, the upper clamp carries the stack. In a three-plate design, the mid carries the stack. Stack spacer height is measured above that supporting surface. With FC stack press nuts enabled, the stack starts directly on the exposed flange. The manual spacer height applies only without stack press nuts. This lift is for the inserts; arm clearance still needs to be checked.')
fields(tab='Stack',padding=6)
para('Stack screw access diameter makes larger service openings in the plate beneath the carrier. Below-bottom arms use these openings in the lower clamp; an upper clamp or mid uses service openings in the bottom. The actual carrier keeps normal mounting bores, or press-nut bores when enabled. Enable arm-root reliefs if arm material crosses a screw-access position. The key also preserves this access.')
table([('Fit stack height','Raises the linked standoff heights to a common size that clears the stack envelope. It does not change the stack support plate or the explicit spacer height.')])
chapter('Standoff counts, positions and heights')
para('Choose four, six or eight standoffs as two, three or four mirrored left/right pairs. Custom positions use pair spacing and Y coordinates. Arm-hole modes snap to the selected inner or outer root bolts and follow later arm adjustments. A nearby hole is not enough: shared holes must be coaxial and have compatible diameters and bearing material.')
figure('StandoffLayouts.png','Extra pairs and shared arm-hole mounts follow the selected support surfaces.',height=230)
fields(tab='Standoffs',prefix='Standoff')
table([('Front standoff height','Actual front-pair length above its support. Editing it adjusts the rear height to keep the top level.'),('Common height shortcuts','Choose common hardware lengths such as 22, 25 or 30 mm, or type a custom value. The linked front and rear sizes remain level.'),('Fit top plate around shared arm mounts','Enlarges top width and length to support the current shared standoff positions. Review the new bounds before building.')])
para('A bottom-mounted standoff in a three-plate frame spans the bottom-to-top distance. A mid-mounted standoff is shorter by the intervening arm and mid thickness. Shared arm-hole standoffs sit on the actual clamping surface, including the mid front tabs. Read the per-pair mounting surface and actual length, rather than assuming every front standoff is bottom-mounted.')
chapter('Top-plate strap openings')
para('Hardware &gt; Straps selects Slots or Outline cutouts, and 1 strap or 2 straps. Use the enable checkbox to turn them on or off. Disabled controls retain their dimensions for later use.')
fields(keys=['StrapSlotsEnabled','StrapOpeningStyle','StrapCount','StrapSingleY'],padding=3)
figure('StrapOpeningModes086.png','Left to right: one strap with slots, two straps with slots, one strap with edge cutouts, two straps with edge cutouts. Front is upward.',height=90)
para('One strap uses its signed position. Two straps use the saved symmetric spacing. Outline cutouts have rounded inner corners. Side guards bridge the unnotched outside edge, leaving the strap passage clear even when separate guard openings are disabled. Mounting, camera-tab and central-web checks remain active.')
fields(tab='Straps',prefix='Strap',padding=2)
chapter('LiPo reference and pad creator')
para('Battery &gt; Placement starts with an editable nominal 1300 mAh 6S reference: 75 x 38 x 38 mm and 208 g. These starting values match the manufacturer specification for the Tattu R-Line 3.0 example, not every 1300 mAh pack. The default reference is a simple clearance box. Optional Detailed LiPo reference adds a shrink-wrapped pack, label, seams, schematic leads and plug. Dimensions refer to the pack body; the displayed leads extend beyond it and do not define routing or swollen-pack clearance. Measure your actual battery and edit its dimensions and mass. Show references controls its visibility together with motors, props and other envelopes.')
para('Choose Top plate or Bottom plate and set X/Y offsets and rotation. Positive X is right, positive Y is forward, and positive rotation turns counterclockwise in top view. The battery and pad share this placement. The battery rests on the pad if enabled, or directly on the selected carbon face. Below-bottom arms or capture plates can restrict the available underside space; resize or reposition the pad if CAD reports an intersection.')
fields(tab='Placement')
sub('Create a separate pad')
para('Battery &gt; LiPo pad creates a separate material part. Choose a rounded rectangle, rectangle, capsule, ellipse, chamfered rectangle, tapered or hourglass outline; set its width, length, thickness and, where applicable, corner radius. Pad dimensions are independent from the battery dimensions. Follow mounting plate clips the pad to the actual finished carrier, including holes, strap slots and applied cutouts. Turning it off retains the independent outline but still requires contact with the carrier. Empty, disconnected or intersecting pads are rejected.')
figure('LiPoPadShapes.png','Eight LiPo pad outlines, including a copy of the finished mounting plate. Existing outline choices remain available.',height=240)
para('Mounting plate outline follows the carrier side profile. Plate outline width scale narrows it across frame X. Pad front reach and Pad rear reach are independent millimetre distances from the FC stack centre, at Stack Offset Y. For example, front 25 mm and rear 35 mm give limits at stack Y + 25 and stack Y - 35. Decreasing either reach cuts that end straight across the frame; it does not compress the plate shape along Y. Zero retains the full carrier at that end. Pad width and Pad length are disabled in this outline mode. All grip patterns now cover the complete finished pad automatically, including narrowed sides and independently trimmed ends.')
para('Every pad leaves at least 6 mm radial clearance measured from each standoff-hole centre (a 12 mm diameter exclusion). These access regions stay at their actual positions and can create edge notches. Carrier openings stay aligned. A pad must remain supported and connected. Older length percentages are converted to front/rear reaches when old settings or documents are loaded. Scaled-pad spline edges in DXF/SVG use line segments with 0.01 mm chord deflection; STEP retains CAD curves.')
fields(tab='LiPo pad',padding=4)
para('Export frame includes the pad in FrameAssembly.step and creates a separate LiPoPad folder containing assembled and flat STEP, a flat STL, and an ungrooved DXF/SVG cutting outline. The STL rests at Z = 0 with the grip face upward. The outline represents through cuts only; shallow grooves are carried by STL/STEP. Pad and reference battery profiles are excluded from carbon nesting sheets. The reference battery is excluded from manufacturing exports.')
para('Sizing reference: <link href="https://genstattu.com/ta-rl3-120c-1300-6s1p.html" color="#237588">Tattu R-Line 3.0 1300 mAh 6S manufacturer specification</link>. The reference box is for placement, not a battery model or electrical/performance recommendation.')
story.append(PageBreak())
sub('Grip pattern catalogue - all 25 surfaces')
para('Every pattern fills the finished pad. Width, depth and spacing are shared controls; all grooves leave a continuous backing. The examples use the same pad, scale and colours.')
from freecad.rotorforge.battery import GRIP_PATTERNS
cells=[]
for name in GRIP_PATTERNS:
 path=DOC/'grip_catalogue'/(name.replace(' ','_')+'.png')
 cells.append([Image(str(path),70,70),p(html.escape(name),'small')])
gripgrid=Table([cells[i:i+5] for i in range(0,25,5)],colWidths=[CONTENT_WIDTH/5]*5,hAlign='LEFT')
gripgrid.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),4),('RIGHTPADDING',(0,0),(-1,-1),4),('TOPPADDING',(0,0),(-1,-1),3),('BOTTOMPADDING',(0,0),(-1,-1),4)]))
story.append(KeepTogether([gripgrid]))
story.append(PageBreak())
chapter('FPV camera cage, tilt and captured tabs')
para('Enable FPV camera drone on Frame &gt; Layout to add the camera side plates and rear VTX mounting holes. Non-FPV designs omit these parts and holes. Video system selects the reference category; measure the actual camera width, body, side screws and VTX instead of relying on a product name.')
para('The two camera side plates are captured between matching sockets in the bottom and top. Upper and lower contact positions can differ, allowing the side walls to slope when the top is shorter. Choose a camera recess under Frame &gt; Top plate when the lens needs uptilt clearance, while retaining the supporting tab sockets. Straight leaves the front solid.')
sub('Body dimensions and side-screw pattern')
fields(keys=['VideoSystem','CameraWidth','CameraHeight','CameraBodyDepth','CameraSideClearance','CameraSideHoleDiameter','CameraSideBoltSpacing','CameraBracketThickness'])
para('Regular two-screw FPV cameras use a vertical pair of side holes when level. Vertical screw spacing is independent of camera width; for example, a 6.5 mm vertical pitch does not describe the width of a mini camera. Zero spacing selects a single friction pivot. Width shortcuts are starting dimensions, not a guarantee that a digital camera or mounting unit matches every mechanical feature.')
sub('Fixed tilt, variable tilt and camera position')
fields(keys=['CameraMountMode','CameraTiltMechanism','CameraTilt','CameraTiltMin','CameraTiltMax','CameraPositionMode','CameraMountY','CameraForeAftOffset','CameraAutoExtend','CameraPivotMode','CameraPivotHeight'])
para('Fixed tilt places the holes at the requested angle. Variable tilt can use dual centred arc slots, which keep the camera body centred, or an upper round pivot with a lower arc, which moves the body around the upper screw. A single-screw friction mount has no mechanical end stops. Check the configured range against the actual camera body and lens.')
para('Camera forward / backward offset adds a relative adjustment to either Automatic centre or Custom position. Positive values move toward the front (+Y); negative values move toward the rear. The reference camera, side holes or tilt arcs, and any flexible pads/inserts move together. Support camera travel automatically grows the middle bearing area of each carbon wall when screws, tilt arcs or TPU flanges need more support. Its top/bottom attachment edges, tongues and plate sockets stay fixed, as do the tilt mechanism, angles and height. Disable it to retain a fixed wall outline. Zero keeps the existing placement wherever support already fits. Use the top-front profile and plate reach to provide clearance over the chosen tilt range. Real body, height, propeller and material clearances still apply, so there is no universal safe travel distance. Native checks cover 10 and 20 mm forward travel with default camera dimensions in all three attachment modes.')
figure('CameraTravel.png','Captured-insert side plates at zero and +20 mm travel: the middle bearing area grows while the top/bottom locating tabs stay at their original positions.',height=190)
figure('CameraMountPatterns.png','Vertical side-screw spacing and camera width are separate measurements.',height=190)
figure('CameraArc.png','The same dual slots allow different tilt angles. Orange markers show the two vertically spaced camera screws moving through the slots.',height=200)
sub('Side walls and attachment contacts')
fields(tab='Side plates')
sub('Independent camera tab positions')
para('Bottom rear, Bottom front, Top rear and Top front tab offsets move the four locating tabs along frame Y. Positive moves forward; negative moves rearward. Both side plates use the same offsets. Matching bottom/top sockets and cutter reliefs follow each tab automatically. The camera, tilt, wall outline and lower/upper contact edges keep their positions. Zero restores the original automatic spacing. Keep each tab inside its contact edge, with enough separation for the neighbouring tab and cutter; required plate support is checked. These offsets move the tabs, not the complete camera cage.')
figure('CameraTabOffsets.png','Teal highlights the locating tabs. Each upper and lower tab can shift independently inside the same carbon wall outline.',height=205)
para('Camera tab shoulder reliefs remove circular cutter clearance beside every upper and lower tongue. The cutter circles lie outside the tab: only the side-plate body is relieved, with a depth equal to half the cutter diameter. A 1 mm cutter produces 0.5 mm depth; a 2 mm cutter produces 1 mm. Enter the actual milling cutter diameter. Tab width, tab height and matching bottom/top sockets remain unchanged. The reliefs appear in the live profile preview, CAD model and DXF/SVG cutting outlines. Disable this option to retain the previous square shoulders.')
figure('CameraTabReliefs.png','Lower tab details. Graphite is carbon; teal circles indicate the cutter diameter. The rounded clearance enters the body above the shoulder, preserving the tongue below.',height=185)
para('Automatic lower attachment sizing follows the camera wall and captured seats. Custom lower front/rear extensions lengthen only the bottom contact edge; its tongues and matching bottom sockets follow that edge. This supports a sloping wall without forcing the same lower and upper contact lengths.')
figure('CameraBase.png','Lower contact extensions let the camera walls reach the bottom while following a shorter or shifted top plate.',height=230)
table([('Fit camera height','Centres the camera and raises linked standoffs to a common size when needed to fit its configured tilt envelope. It does not measure the real camera.'),('Camera width shortcuts','Fill a common body width; use a measured custom width when needed.'),('Vertical pitch shortcuts','Fill a common two-screw side pitch or choose the single-pivot setting. Width and screw pitch remain independent.')])
sub('Move only the upper camera attachment rearward')
para('FPV &gt; Side plates &gt; Upper attachment rearward offset moves the top contact and both matching captured sockets back along frame -Y. It is added after the current fitting settings. The lower edge and camera position stay fixed, including automatic camera centring; the side wall changes slope to connect them. Zero keeps the current design. Existing preferred centre, lower extensions, camera position and tilt controls remain available. Reduce the offset if the checks report lost support or insufficient material around a screw or tilt slot.')
figure('CameraTopRearOffset.png','Left: unchanged upper attachment. Right: upper edge and tongues moved rearward; Rear (-Y) is left; bottom contact and camera screw holes stay fixed.',height=260)
chapter('Rear VTX mounting and coverage')
para('The VTX sits directly on the bottom with two plates or on the mid with three. The reference envelope and estimated centre of gravity start at that carrier surface. Select 20 x 20 mm, 25.5 x 25.5 mm or both hole patterns. Both creates eight possible holes; install one matching set of four fasteners. Hole diameter is separate from spacing.')
figure('VTXCoverage.png','Rear carrier and top-plate coverage in plan, with the VTX envelope in amber. The side section shows the transmitter resting on its carrier below the top plate.',height=230)
fields(tab='VTX',padding=1)
para('Automatic reaches provide mounting support and top coverage. With Custom reaches, extend the carrier and top if the checks report missing support. For lateral overhang, enable a fully covering VTX clearance opening under TPU > Side guards. Mounting holes still need plate support. Verify the real connectors, heatsink and wiring. The VTX envelope is a clearance reference and is excluded from manufacturing exports.')
chapter('Flexible camera interfaces and protective parts')
para('The TPU category creates separate camera isolation parts, motor guards and electronics side guards. Create / Update builds exact solids; editor previews show lightweight footprints and face views without building solids after every adjustment. All protection is optional.')
sub('Colour the printed parts')
para('Open TPU > Appearance and choose Printed part colour. Black, orange, red, blue, teal, lime green, purple, yellow, white and grey apply together to camera compression pads or captured inserts, motor protectors, both electronics side guards and the LiPo pad. Carbon and electronics references keep their own appearance. The selector changes display colour, not geometry, mass, grip texture or material density. STL remains a geometry-only print file; choose the physical filament or silicone colour separately.')
figure('PrintedColours.png','One shared palette for all printed and soft parts.',height=155)
fields(keys=['PrintedPartColour'],padding=5)
para('The overall and individual-part previews use the selected colour. Create or Update applies it to the 3D model and saves it with the frame. Changing colour alone reuses every component and keeps an already calculated weight/CG result. Direct changes in Frame Parameters use the same appearance setting.')
sub('Camera attachment without changing the tilt controls')
para('Hard mount keeps the original carbon side plates and fixing paths. Compression pads add one flexible pad between each camera side and its carbon wall. Captured inserts replace the screw openings in each carbon wall with an adjustable rounded window; the printed insert has a neck through that window and retaining flanges on the selected faces. The existing fixed holes or tilt arc slots are formed in the insert. Keep using the existing FPV tilt, angle range, vertical screw pitch and position controls.')
figure('FlexibleCameraModes.png','Front sections compare hard mounting, compression pads and captured inserts. Graphite denotes carbon, dark grey the soft interface and light grey the camera body.',height=235)
para('In either soft mode, each side gap is pad thickness minus the selected compression. The ordinary Camera side clearance applies to Hard mount only. The free printed pad extends slightly into the nominal camera reference by the compression allowance; this is intentional preload. The pad or insert must contain all screw positions over the current tilt range and stay within the supported carbon wall. Increase the pad/window size or cage dimensions if a check reports missing material.')
fields(tab='Camera isolation',padding=5)
sub('Choose the flexible interface outline')
para('Rounded rectangle uses a rectangular interface with rounded corners. Side plate outline scales the plain camera wall silhouette to the selected pad length/height or insert opening dimensions, centred around the camera mounting pivot. This preserves the wall shape and slope without copying its full size or the tabs captured between the top and bottom plates. The neck, matching carbon opening and retaining flanges use this outline together. Existing fixed holes and variable tilt slots remain unchanged; enlarge the interface if the scaled shape leaves too little material around them.')
figure('FlexibleInterfaceShapes.png','Both captured-insert profiles have rounded corners. Dark grey is the insert; teal traces the matching carbon opening. The side-wall silhouette omits the locating tabs.',height=205)
sub('Rounded captured openings and retaining lips')
para('Under TPU &gt; Camera isolation &gt; Captured insert, set Insert opening corner radius for the carbon opening and matching TPU neck. The default 1 mm radius suits a 2 mm cutter; 0.5 mm suits a 1 mm cutter. Short outline edges can limit the local radius, so choose a cutter that fits the smallest resulting corner. CAD and DXF/SVG profiles retain circular corner arcs. Compression pads and hard mounts keep their existing attachment behaviour.')
para('Retaining lip faces offers Both sides, Outside only or Inside only. Inside faces the camera; outside faces away from it, mirrored correctly on the left and right plates. Both sides is the default. Outside only keeps a soft contact body against the camera and a neck through the opening, but omits the inner flange. Inside only keeps the inner flange and neck without an outer flange. Insert retaining lip controls overlap on whichever faces are selected. Reference camera screws move to the selected outer contact surface; camera position, height and fixed/variable tilt paths stay unchanged.')
figure('CameraInsertLipFaces.png','Sections through both side plates: light grey camera, graphite carbon and dark grey TPU. The contact body and neck remain in all three choices.',height=210)

para('Choose TPU stiffness or silicone to suit the camera and make a fit sample. A flexible interface does not guarantee vibration isolation: over-tight screws, bottomed-out screw threads, or hardware bridging directly to carbon can bypass it. Use suitable screw lengths and compression. Test retention at every working tilt angle.')
story.append(PageBreak())
sub('Bottom-plate front bumper')
para('Enable Create front bumper under TPU &gt; Front bumper to add one slide-on shoe around the finished bottom-plate nose. A sole sits underneath the carbon, a wall protects the edge, and an upper retaining lip captures the plate. The rear is open for fitting. The carbon plate and its existing front-edge profile are not changed. This is a separate printed part in both two- and three-plate frames.')
figure('FrontBumperShapes.png','Six core bumper fronts. Light grey is carbon and dark grey is TPU. Follow bottom plate uses the actual outline; the other styles add a protective toe.',height=300)
figure('FrontBumperSection.png','Fore/aft section: sole below the plate, fit gap around it, edge wall at the front and retaining lip above. Test the fit with your actual TPU and carbon.',height=110)
story.append(PageBreak())
sub('Additional bumper toe profiles')
para('Eighteen bumper shapes include broad swept shoulders, compact flat tips, a centre crown, a faceted shield, a recessed centre and stepped shoulders. Capsule shoe uses a broad flat with rounded ends; Bullnose shoe is a full shallow curved nose. Arrowhead shoe adds a small central flat with swept sides. V-recess shoe leaves an angular centre recess. Twin-shoulder shoe combines rounded outer pads with a recessed flat centre. Clipped-corner shoe uses successive angled shoulders and a flat tip. All toes remain joined to the plate grip through the continuous external shoulder transition.')
figure('FrontBumperMoreShapes.png','Six further toe profiles with swept, crowned, shield, recessed and stepped fronts.',height=380)
story.append(PageBreak())
sub('Rounded, angular and recessed bumper toes')
figure('FrontBumperNewShapes.png','Six further profiles: Capsule, Bullnose, Arrowhead, V-recess, Twin-shoulder and Clipped-corner. Dark grey is TPU; light grey is carbon.',height=390)
para('Toe feature width changes the central flat or recess on supported styles, as a percentage of toe width. Toe recess depth changes the cut-back into the added projection on the four recessed styles. Both use the shape proportions at 0. These controls never cut into the plate grip.')
story.append(PageBreak())
sub('Bumper width and continuous shoulders')
para('Bumper toe width sets the full left-to-right width of a shaped protective toe. Set it to 0 for automatic sizing from the plate grip, or enter at least 8 mm for a custom width. Wider toes provide broader front coverage; narrower toes taper into the grip. The external shoulders blend continuously into the toe, preventing side recesses at the join. The toe outline itself can still have deliberate central recesses, scallops or steps.')
figure('FrontBumperWidth.png','Narrow, automatic and wide toes on the same carbon plate. The grip retains its original plate fit while the outside connects continuously to the chosen toe width.',height=230)
para('Width and extra projection apply to the shaped shoes. Follow bottom plate keeps the actual carbon outline and ignores both controls. Toe width does not scale the plate cavity, wall clearance or retaining lip. A narrow toe can therefore be narrower than the grip behind it. Check camera, wire and side-guard clearances on the finished assembly.')
story.append(PageBreak())
sub('Front shoe controls')
fields(keys=['FlexFrontBumper','FlexBumperShape','FlexBumperWidth','FlexBumperTipWidth','FlexBumperRecess','FlexBumperReach','FlexBumperProjection','FlexBumperLipReach'],padding=4)
para('Lip capture length limits the upper retaining overlap measured backward from the carbon nose. Zero uses the full shoe reach; a custom length must be at least 2 mm and no longer than the shoe. The sole retains its original reach. Test that the shorter lip still retains the printed shoe securely.')
story.append(PageBreak())
sub('Fit and export the front shoe')
fields(keys=['FlexBumperWall','FlexBumperSole','FlexBumperLip','FlexBumperOverlap','FlexBumperFit'],padding=4)
para('Reach is measured backward from the actual foremost carbon edge. The extra toe projection applies only to shaped shoes. Fit clearance surrounds the plate and separates its upper/lower faces from the shoe. Lip overlap controls how far the upper lip reaches inward; lip thickness is its vertical thickness. Use enough wall and sole material for a connected part. A deep notch or short reach can split a follow-outline shoe; change its reach or choose a bridging toe style.')
para('Mounting holes receive at least 6 mm head-access openings through the shoe. Camera tab/side-plate areas and intersecting assembly parts are relieved automatically. Check the finished part around your camera, arm roots and side guards; an unconnected result is rejected. The live view is schematic; created solids and exports contain the detailed clearances. The bumper uses Printed part colour and Flexible material density. Its volume contributes to frame mass and CG. Export writes separate assembled/print STEP files and a bed-aligned FrontBumper.stl in FlexibleParts. Print a fit sample and verify retention before use.')
story.append(PageBreak())
sub('Shape-matched motor protectors and landing feet')
para('Enable Create motor-pad protectors on TPU &gt; Motor protectors to add four separate cups. The outside follows the current motor-pad shape, mirrored rotation and pivot; the cavity clears the actual arm outline and carbon thickness. These are motor/arm-end guards, not propeller guards. Their rim stops below the arm top so it does not form a wall around the motor bell.')
figure('MotorProtectors.png','Carbon arm profile and matching protector underside. The protector floor, screw access and landing foot are separate from the carbon stock.',height=255)
fields(tab='Motor protectors',padding=5)
para('Motor screws uses the active three/four-hole fixing pattern through the floor. Choose screws longer by the underside thickness and verify engagement and winding clearance. Linked screw access makes larger screw-head clearances and connects each radially to the central shaft opening, removing the small bridges between them. Both modes retain the protector perimeter; no tie holes or tunnels are generated. Use suitable hardware and check retention on your actual arm. Landing foot height adds a perimeter foot below the floor; zero gives a flat underside. Print a fit sample before a complete set.')
figure('MotorGuardService.png','Underside profiles: small motor-screw holes and linked screw-head service openings.',height=210)
sub('Electronics side protection')
para('Side guard fit offers Plate-edge wrap (the original design) and Between plates. Between plates moves the full wall thickness inward beneath the plate edges. Its ends seat against the upper face of the bottom plate in two-plate frames, or the mid plate in three-plate frames, and the underside of the top plate. There is no vertical assembly gap: the plates capture the TPU when tightened. Forward sections without a mid plate retain the upper strip; an optional camera closure starts above the bottom plate. Existing saved designs default to Plate-edge wrap.')
figure('GuardInset0891.png','Cross-section through a supported wall: original wrap outside the edges (left); inset wall captured by the top and carrier plate faces (right). Nominal contact, with no vertical gap. The inward setback uses Side guard plate clearance.',height=200)
figure('GuardOptions089.png','Side profiles: original plate-edge wrap with two wire exits; between-plate wall with a joined wire opening; the same wall with additional VTX clearance. Light grey marks the carbon plates. Teal marks the VTX envelope.',height=310)
para('Side guards follow the finished top/mid edges in three-plate frames, or top/bottom edges in two-plate frames. In Plate-edge wrap mode, their wall reaches the top surface of the top plate and the underside of the mid plate with three plates, or the underside of the bottom plate with two. Vertical lips cover the plate edges; the wall between them slopes to follow different widths. Carbon, arm and propeller clearances can trim coverage locally. Where no mid plate supports the forward section, the existing upper strip is retained. The foremost row covered by each guard uses the full exposed post height, with 0.15 mm assembly clearance at each end. Intermediate FC-row sleeves use the upper 10 mm and the rear sleeves use the middle 6 mm. The inboard grip surfaces are circular and the outward supports use rounded capsule profiles instead of square front/rear corners. Both walls use the specified thickness independently of motor-wire opening size. Supporting material connects toward the guard wall to leave room around the electronics. Local arm/clamp reliefs keep the sleeves clear of carbon parts while retaining a continuous inner grip. Exact collision checks reject bearing locations inside a prop sweep.')
para('Side guard plate clearance has a mode-specific direction. Plate-edge wrap uses it as an outward gap from the plate edges. Between plates uses it as an inward setback from the edge to the outer face of the wall; 0 mm makes that face flush with the edge while the full wall thickness stays inside. For example, 1 mm clearance and a 2 mm wall place its outer face 1 mm inward and its inner face 3 mm inward. Increasing it does not add a vertical gap. Plate contact is nominal; verify print dimensions and TPU fit on your hardware. Standoff post clearance is a separate fit setting and remains unchanged. After changing clearance on a saved frame, use Update frame to regenerate its guards.')
sub('Cover the foremost standoffs')
para('Enable Extend to foremost posts to continue each guard to the actual foremost standoff row, including an added pair ahead of the nominal front pair. Existing FC-row bearings remain, so a six-post frame can have three supporting sleeves per side. With only two physical rows, the guard may already reach that row. The top plate must support the selected front posts. Beyond the end of a three-plate mid plate, the wall rises to an upper strip instead of inventing a new mid-plate extension. Front and rear insets shorten the main panel while the bearing sleeves remain attached. In Plate-edge wrap mode the front sleeve encloses its post over the full exposed height even where the adjacent wall follows an upper strip. If the arm or clamp leaves too little room for a continuous sleeve, reposition the post or adjacent carbon part.')
figure('GuardPlateHeight.png','Sections through the side wall: graphite carrier and top plates, dark TPU wall and grey post. Plate-edge wrap covers the full plate-edge height; grips remain on the exposed standoff.',height=220)
para('Top-plate outline strap cutouts stay open beside the guards. Plate-edge wrap bridges the recess along the unnotched outer plate edge. Between plates follows the same smooth reference outline with an inward setback, and clears the actual top-plate strap slots or outline cutouts for 2 mm below the plate so the wall cannot seal their floor. The plate keeps its selected one or two strap cutouts. Widened and tapered plate sides, finishing fillets and unrelated custom outline cuts still determine the surrounding guard profile. The separate Side guard straps controls continue to add optional top- or bottom-edge openings in the guard itself.')
figure('GuardStrapBridge0872.png','Plate-edge wrap top view: the dark guard stays outside the light-grey carbon. The white gap inside the straight guard is the open strap passage.',height=175)
figure('ElectronicsGuards.png','Side profile shows the full-height wall, bearing bands and lower-edge openings.',height=245)
figure('GuardGripHeight.png','Front, intermediate and rear bearing bands compared with their metal posts. Assembly clearance remains at the ends.',height=220)
figure('GuardGripSections.png','Plan sections compare the circular inner sleeve and its rounded outward support.',height=205)
figure('GuardMatchingWidths.png','Plan view of both guards: equal wall thickness and rounded supports at the front and rear posts.',height=235)
sub('Close the sides to the camera plates')
para('On TPU / Side guards / Forward coverage, enable Close sides to camera plates. This adds a broad solid panel from the foremost standoff row forward to the outside rear edge of each actual camera side plate. In three-plate designs, only this forward extension drops to the bottom plate. Plate-edge wrap reaches the plate underside; Between plates seats on its upper face and moves inward under the plate edge. The FC and front-arm area behind that row keeps its normal carrier-height lower edge and motor-wire openings. The panel tapers inward to the camera cage and follows its sloped rear edge when the top and bottom camera contacts differ. Foremost-post coverage is included automatically. The existing camera position and tilt controls remain unchanged.')
figure('GuardFrontClosure.png','The forward closure drops to the bottom plate at the foremost standoffs. The FC/arm area behind them keeps its original lower edge.',height=245)
para('Camera plate landing length sets the overlap along the rear of the camera side plate, from 1 to 8 mm. The landing touches the outside carbon face without thickening the camera cage. In Between plates mode the panel bears on the frame plate faces and plate clearance sets the inward setback. In Plate-edge wrap mode, set plate clearance to 0 mm for nominal edge contact; positive values leave a lateral gap. The camera side plates must span the bottom-to-top opening, and both frame plates must reach the joining area. Existing arm and plate reliefs remain active. USB and motor-wire openings are still optional; inspect their actual positions and cable clearance. The additional camera-side panel is solid, while the existing FC and VTX regions retain their vent choices.')
sub('Clearance for a larger VTX')
para('The optional VTX clearance opening is separate from the vents. On TPU &gt; Side guards &gt; VTX clearance, enable it and choose Left, Right or Both. Automatic dimensions (length or height set to 0) follow the VTX envelope plus the clearance on each edge. Positive dimensions override the corresponding automatic size. Signed fore/aft and vertical offsets move its centre relative to the VTX reference. A low opening continues through the lower guard edge, avoiding a fragile bottom strip. The top web and bearing sleeves remain protected.')
para('A fully covering clearance opening permits a wider VTX to project sideways past the plates. The lower deck must still support all mounting screws, the top and carrier must retain fore/aft coverage, and the generated assembly must clear standoffs, carbon and other parts. A narrow or misplaced custom opening does not waive those checks. If the VTX sits entirely behind the guard, the editor reports that no cut is needed there. This opening requires FPV mode and works with Solid or Vented guards in either fit mode.')
fields(keys=['FlexGuardVTXOpening','FlexGuardVTXSide','FlexGuardVTXY','FlexGuardVTXZ','FlexGuardVTXLength','FlexGuardVTXHeight','FlexGuardVTXClearance'],padding=5)
sub('Independent VTX and FC ventilation')
para('Choose Vented style on TPU / Side guards, then open TPU / Side guard vents. Enable VTX section vents for the rear bay and FC section vents for the forward bay. For vents only near the VTX, disable FC vents. Either section can be used alone; disabling both leaves a solid wall. USB and motor-wire openings remain independent of these switches.')
para('The initial section boundary is the rear FC stack mounting-hole row: stack centre Y minus half its spacing. Vent boundary offset moves this line forward (positive) or rearward (negative), limited to the covered guard length. Adjust it for the actual board edge and VTX location; the mounting row is a reference rather than a universal electronics envelope.')
figure('GuardVentSections.png','Side profiles compare rear-only ventilation with independently shaped VTX and FC openings.',height=270)
para('Each section has its own shape, opening width/height, row count, web, front/rear insets and vertical offset. Vent row counts are unitless whole numbers from 1 to 6; fractional rows cannot be entered. Insets shorten its vented region without shortening the guard. Vertical offsets move rows up or down within the available wall. Travel, row count and height are limited where necessary to retain supporting webs. The shallow strip beyond the mid plate is treated separately. Horizontal slots span each clear section/post bay; repeated shapes use the chosen width. Sleeves and the material around the section boundary remain intact.')
para('The existing six profiles are joined by Circles, Triangles, Inverted triangles, Octagons, Slanted slots, Arrows, Shields, Teardrops, Crosses and Hourglasses. Repeated shapes fit within the width/height envelope and retain the selected web between openings. Narrow details are sensitive to print resolution; check a test print before fitting the guards.')
figure('GuardVentShapes.png','All sixteen profiles are available independently in the FC and VTX sections. Circular openings use the smaller of the requested width and height.',height=350)
fields(keys=['FlexGuardVentBoundaryOffset'],padding=5)
sub('VTX section controls')
fields(keys=['FlexGuardVTXVents','FlexGuardVentShape','FlexGuardVentWidth','FlexGuardSlotHeight','FlexGuardSlotCount','FlexGuardVentWeb','FlexGuardVTXVentRearInset','FlexGuardVTXVentFrontInset','FlexGuardVTXVentZOffset'],padding=5)
sub('FC section controls')
fields(keys=['FlexGuardFCVents','FlexGuardFCVentShape','FlexGuardFCVentWidth','FlexGuardFCSlotHeight','FlexGuardFCSlotCount','FlexGuardFCVentWeb','FlexGuardFCVentRearInset','FlexGuardFCVentFrontInset','FlexGuardFCVentZOffset'],padding=5)
sub('USB cable access')
para('On an extended guard, enable USB access opening and choose Left, Right or Both. Set its fore/aft centre relative to the FC stack, its centre height above the lower carrier, and its width and height. Allow space for the cable plug housing, not just the metal socket. The rounded opening passes through the guard wall. It can now sit close to the top plate. If the remaining strip at the physical top edge would be thinner than the guard wall, the cut automatically continues through that edge. The requested bottom and width stay fixed. Lower-wall support and bearing-sleeve clearance remain required. Keep it disabled when no opening is needed.')
figure('GuardUSBAccess086.png','USB access near the top: a closed opening with adequate upper material, and an automatically opened top edge. Dashed teal line: physical guard top.',height=215)
sub('Bottom openings for motor-wire bundles')
para('With Between plates selected, enabling motor-wire openings creates one continuous lower-edge cutout per selected side. It spans both saved front and rear centres, with half the Motor-wire opening width beyond each end. Height remains adjustable. Motor-wire positions is disabled in this mode; its saved Front / Rear / Both choice is restored when switching back to Plate-edge wrap. The combined cut follows stepped carrier edges and must clear the standoff grips, so it does not add a divider between the front and rear wire positions.')
para('Enable Motor-wire bottom openings when the guard covers the FC/ESC bay. Choose Left, Right or Both sides. Plate-edge wrap offers Front, Rear or Both positions. The two fore/aft offsets are independent and use the stack centre as their anchor; positive values move forward. In Plate-edge wrap, width and height apply to each selected opening. Each notch opens through the local bottom edge and has rounded upper corners, leaving the upper wall connected. Without full front closure, the guard beyond the mid-plate end has an upper strip and the notch starts at that strip’s lower edge. With full closure, the portion ahead of the foremost standoff row starts at the bottom plate. Front openings can span these lower-edge transitions: each portion follows its local carrier edge. FC-area openings retain the original carrier height.')
para('Front openings may approach the front standoff grips. Their cutters are trimmed around the actual bearing sleeves, preserving the sleeve stock and a local 0.8 mm buffer instead of rejecting the complete rectangular opening. The usable opening can narrow beside a grip; increase width or adjust height/position as needed and inspect the created 3D part for your wire bundle. The side schematic retains the grip silhouette, so an outboard passage can be partly hidden in that view. Rear-opening and USB bearing protection retain their existing checks. Openings outside the guard, excessive heights and disconnected results are still rejected.')
figure('FrontWireTravel.png','Front offsets across the mid-plate edge and toward the foremost post. Teal outlines mark the retained bearing bands; actual pockets curve around the sleeves in 3D.',height=260)
para('Motor-wire opening height is measured above the local carrier top. In Plate-edge wrap its lower cut extends automatically through the plate-height lip, so extending the guard does not reduce the existing wire passage. USB and vent locations remain anchored to the internal electronics space.')
figure('GuardWireOpenings.png','Side profile: front and rear bottom-edge exits leave room for motor-wire bundles while preserving the circular post grips.',height=185)
para('Allow space for insulated wire bundles and their bend radius. Rear pockets may pass under a raised standoff grip and open through the rear guard edge. Rear-pocket clearance checks use each grip’s actual height band, retaining at least one wall thickness between the pocket roof and the grip. A rear pocket that reaches the grip height is rejected. It must still intersect the guard wall; moving it entirely behind the guard has no useful effect. Front openings can approach the forward end while preserving the bearing stock. Fit checks also retain material above each opening. If a position conflicts, move the opening or reduce its size. The editor does not model or route actual wires; check the ESC connector positions and cable movement in the assembled frame. This option is independent of Solid/Vented style and USB access, and is enabled separately when needed.')
fields(tab='Side guards',padding=5)
para('Review real USB position, cable bends, cooling, wiring and print fit. No electronics model specifies a universal USB position. The editor provides dimension and side controls so the opening can match your FC.')
sub('Generate, export and estimate flexible parts')
para('Create / Update produces each enabled camera interface, front bumper, four motor guards and/or two electronics guards. Export writes each active part as its own STL and print-positioned STEP in FlexibleParts, with separate assembly-position STEP files and print notes. Camera interfaces and side guards lie on their broad faces; motor cups keep their undersides down. Review supports and orientation in your slicer. These parts appear in assembly STEP and volume-based weight/CG estimates at the flexible-material density, and are excluded from carbon DXF/SVG nesting. Unmodelled antennas, cables and accessories belong in Other equipment / wiring allowance.')

sub('Battery strap access through side guards')
para('Under TPU &gt; Side guard straps, enable Battery strap openings to cut one or two passages through both guards. They open through the selected top or bottom edge, so the strap can pass around the carrier plate. Existing guards are unchanged until this option is enabled.')
figure('GuardStrapOpenings.png','Side-guard-only views: one or two upper passages, and a custom lower passage. Teal outlines identify the strap notches.',height=235)
story.append(PageBreak())
sub('Side-guard strap controls')
fields(tab='Side guard straps',padding=4)
para('Follow plate strap positions uses the top plate single-strap position when one top-plate strap is selected. With two top-plate straps, it uses the front position or both positions according to the side-guard strap count. Disable it to position each opening relative to the stack in frame Y. Opening width is the clear fore/aft span; depth is measured inward from the selected guard edge. Leave material at the opposite edge and keep the full passage clear of standoff grips. Bottom openings in three-plate designs belong in the continuous mid-plate carrier section. Overlapping wire/vent openings may need smaller cuts to keep the panel connected. The preview and printed exports update with the guard; carbon plates and their strap slots are unchanged.')
story.append(PageBreak())
chapter('Airflow openings and shaped plate outlines')
para('Airflow / outlines stores independently editable cutout patterns by part. Select the part, cutting mode and shape, set its position and dimensions, then press Add pattern. To modify a saved pattern, select it and press Apply to pattern after editing. The preview and generated model use saved enabled patterns.')
table([('Part','Chooses the target carbon component. Settings for inactive parts are retained until that component is enabled.'),('Cutting mode: Interior','Makes an enclosed opening while preserving the required material to existing edges, holes and fasteners.'),('Cutting mode: Outline notch','Intentionally crosses an outside edge of the bottom, mid, top or a clamp plate. Each instance must overlap material and extend outside. Arms, keys and camera side plates retain Interior patterns.'),('Cutout type','Chooses one of the twenty profiles described below.'),('Width / length','Sets the local shape size. Circle uses width as its diameter.'),('Centre U / V','Horizontal parts use frame X / Y. Camera side plates use U along frame Y from the nominal camera centre, and V as height above the bottom upper face.'),('Rotation','Rotates the cutout and its centred repetition grid.'),('Columns / rows','Repeats the shape in a centred grid. Each enabled copy counts toward the frame cutout limit.'),('Pitch U / V','Spacing between grid centres, before rotation. Pitches smaller than the cut dimensions can create overlapping copies.'),('Enabled','Keeps the pattern saved while including or excluding it from the model.'),('Saved patterns / Enabled cuts','Shows the capacity used. Up to 200 patterns can be stored and at most 200 instances enabled, including grid copies.'),('Add pattern','Appends the current controls as a new saved pattern. Failure shows a warning and preserves the saved list.'),('Apply to pattern','Replaces the selected saved pattern with the current controls.'),('Remove','Deletes the selected saved pattern.'),('Discard unapplied changes','Restores the saved control state without changing existing patterns. Unapplied edits must be added, applied or discarded before checking, saving settings or building.'),('Copy to other camera side','Adds an independently editable copy of the current camera-side pattern to the opposite camera plate.'),('Check plate cuts in CAD','Builds the actual solids and checks complete geometry without creating or updating the frame document objects.')],padding=2)
story.append(PageBreak())
sub('Find an existing cutout')
para('Use Find cutout above the saved list to search by pattern number, shape, part name, cutting mode, dimensions or centre coordinates. Multiple words must all match. Enter #12 to find exactly pattern 12. The part filter narrows the list without changing saved patterns. Selecting a result opens that part and loads its controls. Numbers follow the saved list order and can change after deletion; they are locator labels, not permanent part names.')
figure('CutoutLocator.png','The list and preview share the same pattern numbers. Orange identifies the selected pattern, even when its opening merges with another cutout. Preview detail shown.',height=205)
table([('Click an opening or number','Selects its saved pattern. Clicking any member of a repeated array selects that entire array. Clicking again at the same overlapping opening cycles through the matching visible patterns.'),('Show pattern numbers','Shows labels for visible enabled patterns on the current preview part. The selected pattern always has its number and highlighted outline.'),('Zoom to selected / Fit plate','Magnifies the selected pattern and its array copies. Fit plate returns to the complete part.'),('Filters and hidden selections','The count shows how many patterns match and identifies a selected pattern hidden by the filter. Apply and Remove show the selected number. Clear the search or choose All parts to reveal more results.'),('Disabled patterns','Remain searchable in the list. Select one there to inspect its dashed outline; it stays excluded from generated cuts until enabled.'),('Unapplied edits','Apply or discard edits before selecting another pattern. Switching results cannot silently overwrite the current controls. Search, filtering, highlighting and zoom do not build CAD or change saved geometry.')],padding=3)
para('After editing, press Apply to #number to update the selected saved pattern. The existing geometric checks still run when you check, create, update or export the frame. Pattern arrays and overlapping shapes keep their original editing behaviour.')
story.append(PageBreak())
sub('Cutout catalogue - all 20 shapes')
para('These coloured silhouettes show the material removed. They use the exact editor geometry, one scale and an 8 mm width by 12 mm length envelope. Circle uses width as its diameter. Rotation turns the profile and its repetition grid together.')
from freecad.rotorforge.cutouts import CUTOUT_TYPES
cut_descriptions=('Width is diameter.','Capsule, round ends.','Radius = min(W,L)/4.','Six straight sides.','Independent width/length.','Square corners.','Point faces local +V.','Four pointed corners.','Narrower toward +V.','Five straight sides.','Eight clipped sides.','Concave V opening.','Seven straight sides.','Twelve straight sides.','Slanted quadrilateral.','Offset broad shoulders.','Narrow centre waist.','Four joined branches.','Curved concave opening.','Pointed curved oval.')
cells=[]
for name,description in zip(CUTOUT_TYPES,cut_descriptions):
 path=DOC/'cutout_catalogue'/(name.replace(' ','_')+'.png')
 cells.append([Image(str(path),78,68),p(html.escape(name),'small'),p(html.escape(description),'small')])
cutgrid=Table([cells[i:i+5] for i in range(0,20,5)],colWidths=[CONTENT_WIDTH/5]*5,hAlign='LEFT')
cutgrid.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),4),('RIGHTPADDING',(0,0),(-1,-1),4),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),8)]))
story.append(KeepTogether([cutgrid]))
story.append(PageBreak())
sub('Combine openings and cut plate edges')
figure('CutoutCombinations.png','Combined openings formed by overlapping editable source patterns.',height=230)
para('Overlapping patterns on the same part are united before subtraction. Different shapes and grid copies can combine, and an Interior opening can overlap an Outline notch. Merely tangent shapes do not merge: overlap them or leave at least the configured minimum material between separate cuts. Existing holes, sockets and fastener bearing footprints remain protected. A union that disconnects the part or isolates an island is rejected.')
figure('Outline_Notched.png','The same top plate before and after edge cuts. White cutouts remove material; the coloured plate remains connected around its mounting holes.',width=479,height=210)
para('A pattern wholly inside the plate belongs in Interior mode. A pattern wholly outside removes no material and is rejected as a notch. In a grid, every notch instance must cross an outside edge. If a saved design already has many patterns, check the capacity readout; use the displayed limits before adding more cuts.')
chapter('Checks, references and dimensions')
sub('Calculate frame weight and centre of gravity')
para('Click Calculate frame weight / CG beneath the preview to evaluate the current geometry before creating a document. Apply or discard pending airflow/outline edits first. The calculation uses finished CAD solid volumes, including holes, cutouts and grip grooves. It reports carbon mass separately and adds the modelled hollow standoff tubes and optional pad using their own densities. Active flexible parts, including guards, camera interfaces and the front bumper, contribute at the flexible-material density. Frame CG is the mass-weighted centre of those parts in frame X/Y/Z coordinates. A result can lie inside the structure; the editor marks its top-view projection with a red cross.')
para('The bare Frame and Frame + reference LiPo results remain available. Hardware &gt; Weight estimates adds a separate Equipped result (without LiPo) and Equipped + LiPo result. These include four motors, four props, one FC and one 4-in-1 ESC, plus the camera and VTX when FPV mode is enabled. Standoffs use their actual hollow geometry and density, so longer front standoffs and changed pair counts affect the result without being counted twice. Screw counts follow the mounting geometry; shared arm/standoff bolts replace separate base screws.')
para('Defaults are editable representative planning values, not a market-wide statistical average. FC 10.5 g and ESC 23.5 g follow the SpeedyBee F405 V4/BLS 55A specifications; motor 30.5 g follows the iFlight XING2 2207 specification. Camera/VTX 10 g each, props 4 g each and Other equipment 15 g are nominal allowances. Change masses for your actual motor size and analog/digital equipment. Zero omits an item. Visibility never changes mass inclusion.')
para('CG uses mass-weighted component centres. Motor positions follow the actual rotated pad centres; FC/ESC centres follow the stack deck; camera follows its body centre; VTX follows its rear envelope. Other equipment is concentrated at the stack centre. Screw positions and lengths are approximations. The red cross uses Equipped + LiPo CG when available, Equipped CG without the reference battery, or bare Frame CG when equipment estimates are off. Verify final aircraft mass and balance with the actual hardware.')
fields(tab='Weight estimates',padding=5)
sub('Where nominal values come from')
para('Manufacturer references: <link href="https://www.speedybee.com/speedybee-f405-v4-bls-55a-30x30-fc-esc-stack/" color="#08798a">SpeedyBee F405 V4 / BLS 55A specifications</link>; <link href="https://shop.iflight.com/index.php?product_id=2587&amp;route=product/product" color="#08798a">iFlight XING2 2207 specifications</link>. Other defaults are declared allowances. Actual builds vary, especially digital video hardware, heatsinks, wiring and motor size.')
para('Calculations do not create a document. Editing parameters marks the result out of date and removes the old preview marker. Calculate again to refresh it. Create / Update also stores the current results in Frame Parameters. Show estimated CG marker and Show references control the 3D cross; they do not include the marker or reference envelopes in frame mass. Export writes the values, material densities and scope to MassProperties.json and ExportInfo.json.')
fields(tab='Checks')
table([('Status','Reports whether the current generated geometry is valid or which error prevents building it.'),('Warnings','Lists layout conditions to review. A valid model can still have warnings.'),('CarbonMassGrams','Finished carbon-only mass from exact solid volume and carbon density.'),('FrameMassGrams / FrameCG','Carbon, modelled standoff tubes and optional pad; CG is the mass-weighted X/Y/Z position in mm. Unspecified hardware and electronics are excluded.'),('FramePlusBatteryMassGrams / FramePlusBatteryCG','Frame estimate plus the reference battery only, using the entered battery mass at its envelope centre. Not full aircraft weight/CG.'),('EquippedMassGrams / EquippedCG','Bare frame plus enabled nominal equipment, screws and extra allowance, without battery.'),('LoadedMassGrams / LoadedCG','Equipped estimate plus reference LiPo, when both options are enabled.'),('MinimumPropGap','Calculated closest propeller edge-to-edge gap.'),('GeneratorVersion','Plugin version that generated or recomputed the frame.')])
para('Errors block creation when the fast checks detect invalid dimensions or missing support. Detailed CAD checks run on Create / Update, explicit cut checking and Export. Warnings describe conditions to review, such as a smaller-than-desired prop gap. Neither a warning-free model nor the carbon mass estimate calculates crash strength, stiffness or vibration behaviour.')
para('Reference envelopes show approximate props, motors, FC/ESC stack, camera and VTX. They are excluded from STEP and cutting profiles. Carbon mass uses the configured density and generated carbon volume; equipment weights are assigned separately through the nominal estimation controls. Check real mounting dimensions, connectors and screw engagement against the intended parts.')
story.append(PageBreak())
sub('Optional detailed presentation references')
para('Finishing &gt; Detailed references contains independent switches for motors, three-blade props, FC/ESC stack, FPV camera, VTX and LiPo. Leave them off to keep the original simple references. Enable Show references first; camera detail also requires FPV. Create or Update applies the selected style to the 3D document. The editor keeps its fast schematic plan view.')
figure('DetailedReferences.png','Generic presentation models built from the current dimensions: outrunner with a seated 6 mm hub and M5 locknut, 3.7-inch-pitch three-blade prop, two populated PCBs with silicone grommets, and FPV camera.',height=225)
fields(keys=['DetailedMotorReferences','DetailedPropReferences','DetailedStackReference','DetailedCameraReference'],padding=4)
para('Detailed hubs sit at bell height; simple-disc height is ignored. The grey stator starts at the lower bell edge, with a dark support down to the feet and 0.5 mm radial mounting-screw clearance. Windings stay inside the bell. Stack/camera settings, mass estimates and manufacturing exports are unchanged. Models stay cached; detailed-prop clearance covers the swept blade-height range.')
story.append(PageBreak())
sub('FC USB reference and guard alignment')
para('The detailed upper FC board now includes a hollow USB-C shell and internal tongue, using a generic side-centred commercial-style location. The SpeedyBee F405 V4 manufacturer layout is a reference for a side-facing connector; this is not a dimensionally exact model of that FC. The shell is 9 mm wide, 3.2 mm high and 7.5 mm deep, extending 0.8 mm past the reference PCB. Its bottom sits on the upper PCB face.')
figure('FCUSB085.png','Detailed FC/ESC stack with the USB-C receptacle on the left edge of the upper board. Left/right placement and fore/aft offset are adjustable.',height=210)
fields(keys=['StackUSBFace','StackUSBOffsetY'],padding=4)
para('The editor summary reports the matching side-guard USB centre Y offset and Z height, including stack spacers and carrier height. Enter those values under TPU &gt; Side guards &gt; USB access, select the matching side, and allow extra width/height for your actual cable plug. Guard USB access requires forward guard coverage. Changing the reference does not automatically move or resize an existing guard opening. The connector is visual only; check the actual FC and cable, since the simple stack collision envelope does not include this protrusion.')
para('Source: SpeedyBee F405 V4 60A Stack manufacturer manual, Layout and Dimensions: https://www.speedybee.com/f405-v4-60a-stack-download/')
story.append(PageBreak())
sub('FC and ESC grommet contact')
para('The detailed stack uses two PCBs. ESC grommet necks point upward and FC necks point downward, meeting between the boards. Only a short retaining flange sits above the FC PCB. The upper nuts remain seated at the selected total stack height, directly above that flange; no extra stack offset is added. Lower grommets start at the existing stack mounting level, including any press-nut adjustment.')
figure('StackGrommetContact.png','Side section of one screw position: green PCBs, dark grommets and nut, grey screw shank. The teal line marks the contact between the opposing grommet necks.',height=290)
story.append(PageBreak())
sub('Optional detailed VTX and LiPo references')
para('The additional power references use the same independent switches and Show references control. VTX detail requires FPV; LiPo detail requires Battery reference enabled. Their appearance is independent of Printed part colour.')
figure('DetailedPowerReferences.png','Generic VTX board with shield and cooling fins, and shrink-wrapped LiPo with label, seams, leads and plug. These are presentation models, not exact commercial products.',height=200)
sub('Power reference controls and placement')
fields(keys=['DetailedVTXReference','DetailedBatteryReference'],padding=5)
para('The VTX stays on its existing carrier plate, follows the current mounting-hole pattern and uses its current width, length and height. Analog and digital modes show one or two generic RF sockets. The LiPo pack body follows Battery width, length and height, its X/Y position, rotation and top/bottom mounting; the label faces away from the frame. Schematic leads and plug extend beyond the body and require their own routing clearance. Body-envelope checks, weight/CG estimates and manufacturing exports stay unchanged. Keep simple references for fast editing and enable detail when preparing a design image.')
story.append(PageBreak())
chapter('Hardware references and nut retention')
sub('Low-profile round screw references')
para('Select a generated frame and choose Hardware references from the RotorForge menu or toolbar. Select Arm bolts, Motor screws, Standoff screws, Stack hardware, Camera screws or VTX hardware. Create / refresh references builds simplified round button-head screws at those mounting positions. Nominal thread engagement adds 0.5–10 mm into threaded motor, camera and standoff holes. References have no modelled threads and are not rounded to stock screw lengths; check the purchased hardware and real thread depth.')
figure('HardwareReferences.png','Black round button heads at the arm mounting positions. Hardware is a display reference, excluded from manufacturing solids and any second weight estimate.',height=190)
para('Reference screws, conventional nuts and press nuts have a black finish. Refreshing existing references applies the finish while retaining unchanged fastener geometry and visibility. This is display appearance only; it does not change hardware dimensions or mass. Show arm retaining hardware controls the arm nut and press-nut reference shapes. Stack hardware includes conventional upper nuts and the selected optional lower press nuts. VTX hardware uses screws only. Hide references and Show references change visibility only. Save the FCStd to retain reference settings. Once created, hardware references follow valid frame changes automatically, including upper nuts and optional press nuts. Your selected hardware groups and hidden states are retained. Unchanged fasteners reuse their existing geometry. Invalid edits pause the references until the frame is valid again. Existing equipment and screw mass allowances remain independent.')
sub('Receiving-plate nut seats')
para('Open Hardware &gt; Nut retention in the frame editor. Arm nut retention selects External hex nut, Recessed hex nut or M3 press nut. FC stack press nuts independently enables M3 inserts at the four stack mounting holes. The choices change the real receiving-plate geometry after Update frame; they are not just display settings. Arm retention applies to non-shared arm bolts. Shared arm/standoff bolts continue to enter the threaded standoff. Motors and camera bodies retain their own threaded holes. The FC stack keeps conventional upper nuts even when lower press nuts are selected. Motors, cameras, standoffs and VTX joints receive no retention inserts from these options.')
para('With three plates, the mid plate receives arm nuts. In a two-plate design with above-bottom arms, the upper clamp receives nuts when enabled; otherwise the underside of the bottom plate receives them. With below-bottom arms, the upper face of the bottom plate receives nuts, including when a lower clamp is enabled. VTX screws run up from beneath the carrier into the transmitter mounting points; no VTX nuts or retention cutouts are generated. Only one four-hole VTX pattern is populated when both patterns are drilled.')
figure('NutSeats.png','Section examples in a 3 mm plate. A hex pocket partly sinks a conventional nut. A press nut uses a mounting bore through the receiving plate; its shank depth is an insert dimension, not a blind-hole depth.',height=160)
fields(keys=['ArmNutMount','StackPressNuts','NutRecessDepth','NutRecessClearance'])
para('Nut pocket fit allowance adds to the nominal hex nut width and to a circular flange-pocket diameter. The recess may be partial: do not remove all the plate thickness merely to make a nut flush. The builder requires at least 1 mm of carbon below a hex pocket and checks the bearing rim against the finished plate outline and other cuts. A pocket with insufficient stock is rejected; widen the plate or change the bolt position. Account for the cutter radius and nut corners in CAM; a sharp mathematical pocket may require corner relief or a small cutter to seat a real nut.')
sub('M3 press nuts and the correct mounting bore')
para('The defaults follow the documented KF2/KFS2 M3 broaching-nut family: 4.22 mm mounting hole (+0.08 mm), 1.53 mm maximum shank and minimum sheet thickness, 5.56 mm flange diameter and 1.50 mm flange height. These are a specific insert family, not universal dimensions for every M3 press nut. FPV insert suppliers also specify different fits, including 4.50–4.55 mm holes. Match the purchased insert drawing before manufacture; M3 describes the thread, not the required carbon mounting bore.')
fields(keys=['PressNutBore','PressNutFlangeDiameter','PressNutFlangeHeight','PressNutShankDiameter','PressNutShankDepth','PressNutFlangeRecess','PressNutMinThickness'])
para('The mounting bore passes through only the receiving plate. Set flange recess to zero to leave the flange outside, or machine a circular flange counterbore to lower it. The remaining plate must satisfy both the minimum sheet thickness and shank length. M3 press nuts require a compatible M3 joint and FC board holes when used at the stack. The receiving plate must retain a full 1 mm material margin around the press-nut flange or flange counterbore, including near other openings. With FC stack press nuts enabled, the stack underside rests directly above the exposed flange, without an added vertical gap. Round button-head screws start beneath the supporting plate, pass through the press nuts and stack, and retain conventional nuts above the stack. Fit stack height includes those upper nuts when selecting taller standoffs. Broaching/press-in inserts are different from long blind-rivet nuts used for sheet metal; installation and pull-out strength in carbon must be verified with your actual insert and laminate.')
para('Dimensional references: <link href="https://www.penn-eng.com/cn/product/kfs2-m3/" color="#08798a">PennEngineering KFS2-M3</link>; <link href="https://www.jinjiuyi.net/press-nuts/KF2-KFS2-M3-press-nuts.html" color="#08798a">Jinjiuyi KF2/KFS2 M3</link>; <link href="https://www.jinjiuyi.net/nut/M3-Press-Nut-for-FPV-Racing-Drone-sunk-nut.html" color="#08798a">FPV press-nut fit guidance</link>.')
sub('Manufacturing files and preview scope')
para('STEP and the native solids contain the real blind pockets and enlarged press-nut mounting bores. DXF/SVG profiles contain through cuts only: they do not turn a shallow hex or flange pocket into a through hole. MachiningOps.csv lists each secondary pocket, receiving face, frame and individual DXF coordinates, depth and either across-flats width or counterbore diameter. Add these pocket operations in CAM before cutting stock. The editor profiles show through bores; inspect the generated 3D parts for shallow seats. Carbon mass uses the machined volume.')
chapter('Save, reload and update a design')
sub('Continue editing a saved frame')
para('Opening an FCStd keeps its saved solids. Loading JSON refreshes settings and the 2D preview without building a new assembly. Apply Create / Update when ready. Direct parameter edits in FreeCAD regenerate when the document recomputes. Calculate weight / CG, Check plate cuts in CAD and Export also request exact geometry. Correct reported errors before retrying a failed build.')
sub('Reuse unchanged components')
para('RotorForge rebuilds affected parts and their dependencies. A plate change can affect its camera contacts, pad or guards; a layout change can affect most of the frame. Vent, USB and wire edits can reuse the solid guard shell and grips. Weight allowances update estimates without remaking carbon. Identical updates leave component Shapes in place. Validation and assembly checks remain active.')
table([('LastBuildSeconds','Geometry build time for the last update; document display and export time are additional.'),('RebuiltComponents','Components rebuilt for the last update.'),('ReusedComponents','Components served from the dependency cache.')],padding=4)
para('These read-only values appear under Frame Parameters / 09 Results. Times depend on the design and computer.')
sub('Reuse geometry after restarting')
para('Save the FCStd after updating to retain verified component geometry. RotorForge also keeps a bounded local cache of successful builds, so creating the same JSON settings again can reuse native parts after a restart. The cache holds at most eight designs and 128 MiB. Full settings and generator, FreeCAD and OpenCASCADE versions must match; stored data and shapes are verified before use. Missing, incompatible, damaged or unwritable cache storage falls back to normal generation. The first build of a new design, on another computer or after an upgrade can take longer. JSON files themselves contain settings, not solids.')

chapter('Export and prepare a CNC cutting layout')
para('Select a frame, one of its parts, or its cutting-layout objects and choose Export frame. Choose an output directory. A new timestamped subfolder is created for every export, so previous files are not overwritten. Export also refreshes this frame\'s <b>Cutting profiles (DXF / SVG)</b> group in the same FreeCAD document. Save the project to retain that group.')
sub('Native cutting profiles in the open project')
para('The cutting group is placed beside the assembly and contains one stock subgroup per thickness. Each physical carbon part appears once as an exact planar face on XY, including its outer perimeter, holes, slots, airflow openings and notches. Camera side plates are flattened from their assembled YZ orientation. There is one contour set shared by the DXF and SVG representations, rather than duplicate overlapping imports.')
para('The root group has a movable placement. Stock subgroup origins correspond to the lower-left origins of the matching stock files. Each child links to its source part and records thickness. Re-export refreshes the snapshot instead of adding duplicate groups; a manually moved root origin is retained. Undo can restore the previous snapshot. Editing the frame does not automatically update a snapshot: export again when ready.')
figure('CuttingSheets.png','The export planner separates stock thicknesses and alternates arm ends. Sheets use independent display scales.',height=250)
para('Create the CAM job from a stock subgroup using its local origin. Verify millimetre units, stock/material and cutter access to holes and slots. Cut internal contours before the outside perimeter.')
sub('Spacing, stock thickness and scale')
para('All files are 1:1 in millimetres. The four arms are rotated upright and placed side by side in one row. Motor ends alternate top, bottom, top, bottom, with 4 mm bounding-box clearance between arms. Rotation preserves each arm\'s handedness and hole geometry; no part is mirrored. Other parts keep their flattened axes and use 12 mm gaps. All sheets have a 10 mm margin. Remaining parts use shelf rows targeting 420 mm; a complete arm row or oversized part can exceed that width without scaling. Different thickness sheets are separated by 30 mm in the combined overview.')
para('This is an alternating arm arrangement with conservative bounding-box clearance, rather than contour-interlocking nesting or G-code. Choose actual stock dimensions, fibre direction, holding tabs and cutter compensation in CAM. The profiles have no cutter-radius or kerf compensation, dogbones or automatic machining allowances. Stock thickness metadata describes the parts; it does not create a CAM stock model.')
table([('FrameAssembly.step','Assembled carbon parts, standoff tubes, optional LiPo pad and active flexible parts, including the front bumper and side guards. Reference envelopes are excluded.'),('CuttingProfiles / part DXF and SVG','An individual local-origin profile for each physical carbon part.'),('CuttingProfiles / Stock_&lt;thickness&gt;.dxf and .svg','A separate sheet for each stock thickness, with the same local part positions as its native stock subgroup. These sheets contain no text that could be mistaken for a cutting contour.'),('CuttingProfiles / AllCarbonParts.dxf and .svg','An overview of all thickness sheets, separated into bands. Keep different thicknesses separate when machining.'),('CuttingProfiles / Layout.json','Exact units, margins, gaps, stock-sheet sizes and part placements.'),('FrameParameters.json','Editable settings, including battery/pad parameters and all saved cutout patterns.'),('MassProperties.json','Bare-frame, nominal equipment and loaded masses and CG, per-item equipment assumptions, material densities and explicit scope.'),('LiPoPad / STEP, STL, DXF and SVG','If enabled, a separate pad assembly/flat model, printable STL and through-cut outline. Shallow grip grooves appear in 3D files; pad profiles do not enter carbon nesting.'),('EquipmentMass.csv','When enabled, equipment and screw estimates with mass and X/Y/Z centre for each item. Together with the bare frame these reproduce the Equipped result; the battery is added only to Loaded.'),('PartsList.csv','Carbon/pad and modelled standoff unit masses, stock thicknesses and hardware summary. Multiply mass by Quantity; blank masses are unassigned. Fastener grip is not total screw length.'),('ExportInfo.json','Generator version, warnings, mounting geometry, hole patterns, clearances and cutting-layout data.'),('READ_ME_FIRST.txt','Manufacturing notes for the exported design.'),('CameraPlates / STEP and STL','In FPV mode, separate assembled STEP and flat printable STL files for the camera sides. Their carbon cutting profiles are also included in the normal sheets.'),('MachiningOps.csv, when present','Secondary operations such as countersinks, separate from the through-cut profiles. Follow the per-export notes.')],padding=1)
chapter('Common tasks and troubleshooting')
table([('A loaded design will not accept another cut','Check the capacity readout. The editor accepts up to 200 patterns, with at most 200 enabled instances. Reduce grid copies or disable an existing pattern if the enabled budget is full.'),('The preview or model ignores my latest pattern controls','Press Add pattern for a new cut or Apply to pattern for an existing one. Discard unapplied changes restores the saved state. Then check and update the frame.'),('An outline notch is rejected','Place it across an actual outer edge of a supported plate. Check centre widening, existing holes, captured sockets and standoff bearing material. Every grid copy must cross an edge.'),('A combined cut is rejected','Overlap shapes instead of merely touching them, or increase the material between separate openings. Avoid cuts that separate the plate or isolate a carbon island.'),('Arm roots do not meet','Use Fitted miters, bring root references inward and increase tail extension. Root width enlarges material, but joint trimming does not automatically move or extend the roots.'),('The key is too large','Use the compact fitted-miter key controls. Arrange roots and tails so they meet the intended key pocket, then verify bolt support and screw access.'),('A widened arm creates plate overhangs','Review the main-body width and reach separately from the arm-matched tabs. Mid front and bottom rear tabs follow their respective arms; an intentionally extended main body is not trimmed away.'),('The camera hits a plate or cannot tilt through the range','Check actual dimensions, measured vertical screw pitch, cage clearance and top camera cutout. Use Fit camera height if more height is needed.'),('The lower camera wall does not reach far enough','Enable plate-end following and use Custom lower attachment sizing to extend the front/rear bottom contact independently.'),('The stack or VTX has no clearance','Check the supporting plate and electronics envelope. Increase standoffs for headroom; Fit stack height adjusts for the FC/ESC. Extend Custom reaches to support the VTX and its top coverage.'),('Shared standoff holes are rejected','Use an arm-hole snap mode and compatible hole diameters. Check the actual carrier and its full bearing footprint; approximate manual alignment is insufficient.'),('The cutting layout looks outdated','Re-export the frame. The document group is an export snapshot, not an automatically recomputed dependent model.'),('I need a different CNC origin or sheet position','Move the cutting root or stock subgroup as needed, and use the matching sheet origin in CAM. Re-export rebuilds the planned child placements and retains the root placement.'),('A saved project cannot find the workbench','Install the complete RotorForge folder for that FreeCAD user and restart FreeCAD. See the separate Installation PDF for platform paths.'),('A help image or guide is missing','Reinstall the complete plugin package. The Help command opens the PDF stored beside the plugin code.')],padding=3)
assert len(used)==len(controls),(len(used),[c['key'] for c in controls if c['key'] not in used])
# Insert a linked contents table after the chapters are known.
toc=Table([[p(f'<link href="#{key}" color="#08798a">{i:02d}  {html.escape(title)}</link>')] for i,(title,key) in enumerate(chapters,1)],colWidths=[CONTENT_WIDTH]);toc.setStyle(TableStyle([('BOTTOMPADDING',(0,0),(-1,-1),3),('TOPPADDING',(0,0),(-1,-1),3),('LEFTPADDING',(0,0),(-1,-1),0)]));story.insert(toc_marker,toc)
class GuideDoc(SimpleDocTemplate):
 def afterFlowable(self,flowable):
  if isinstance(flowable,Paragraph) and flowable.style.name=='h' and 'chapter-' in flowable.text:
   key=re.search(r'name="([^"]+)"',flowable.text).group(1);self.canv.bookmarkPage(key);self.canv.addOutlineEntry(flowable.getPlainText(),key,0)
def page(c,doc):
 c.saveState();w,h=A4;c.setStrokeColor(LINE);c.line(52,h-42,w-52,h-42);c.line(52,42,w-52,42)
 c.setFillColor(ACCENT);c.setFont('Bold',9);c.drawString(52,h-31,'RotorForge')
 c.setFillColor(INK);c.setFont('Body',8);c.drawRightString(w-52,h-31,'Drone Frame Editor • Help')
 c.drawString(52,29,'Help manual / '+__version__);c.drawRightString(w-52,29,str(doc.page));c.restoreState()
pdf_buffer=io.BytesIO()
doc=GuideDoc(pdf_buffer,pagesize=A4,leftMargin=52,rightMargin=52,topMargin=61,bottomMargin=57,title='RotorForge - Complete user guide',author='RotorForge')
doc.build(story,onFirstPage=page,onLaterPages=page)
OUT.parent.mkdir(parents=True,exist_ok=True)
temporary=OUT.with_suffix('.building.pdf')
temporary.write_bytes(pdf_buffer.getvalue())
os.replace(temporary,OUT)
assert OUT.stat().st_size>100000
(DOC/'help_coverage.json').write_text(json.dumps(dict(version=__version__,described_controls=sorted(used),chapters=[c[0] for c in chapters]),indent=2))
print('Rebuilt',OUT,'with',len(used),'controls in',len(chapters),'integrated chapters')
